    + '<div class="pxp-set"><span>Size</span>' + pxSeg([["normal", "Normal"], ["large", "Large"], ["floor", "Shop floor"]], sizeMode(), "set-size", "data-size") + '</div>'
    + '<div class="px-sep"></div>'
