function ivIco(k, sz){ var b = IVI[k]; if(!b) return ''; sz = sz || 16; return '<svg class="px-ico" width="'+sz+'" height="'+sz+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+b+'</svg>'; }
function ivTheme(){ try{ return /^iv[ld]$/.test(resolvedTheme()); }catch(e){ return false; } }
function ivDesk(){ return ivTheme() && document.documentElement.getAttribute("data-device") !== "phone"; }
var IV_NAV_IC = { console:"console", ros:"ros", rolist:"ros", triage:"triage", foreman:"foreman", warranty:"warranty", manager:"manager", parts:"parts", timelog:"timelog", fixes:"fixes", career:"career", inbox:"inbox" };
/* "WAITING – PARTS" → "Waiting – Parts", "COMPLETE – ROAD TEST" → "Complete – Road test"; the op-type codes stay */
var IV_CAPS_KEEP = /^(DIAG|OP|PM|WARR|COMEBACK|SUBLET|RECALL|REPAIR|VIN|RO|ETA|PO|AM|PM|OK|QR|ID|EOD|CSV|PDF)$/;
function ivCase(t){
  if(!t || !/[A-Z]/.test(t) || /[a-z]/.test(t) || IV_CAPS_KEEP.test(t.trim())) return t;
  return t.toLowerCase().replace(/^([^a-z]*)([a-z])/, function(m, a, b){ return a + b.toUpperCase(); })
    .replace(/([–-]\s+)(\S)/g, function(m, a, b){ return a + b.toUpperCase(); }).replace(/\bro\b/g, "RO").replace(/\bvin\b/g, "VIN");
}
function ivCaseFix(root){
  if(!root || !ivTheme()) return;
  root.querySelectorAll(".chipMain, .chipSub, .chipTxt, .jobStTxt, .menuItem > span:nth-child(2), .pill, .st-opt, .ty-st, .rl-st, .mr-dot, .tyc-st").forEach(function(n){
    if(n.children.length) return;
    var t = n.textContent, u = ivCase(t); if(u !== t) n.textContent = u;
  });
  root.querySelectorAll(".subChip, .pill").forEach(function(n){
    var tn = null; n.childNodes.forEach(function(c){ if(c.nodeType === 3 && c.textContent.trim()) tn = c; }); if(!tn) return;
    var t = tn.textContent, u = t.replace(/(^|[–·]\s*)([^–·]+)/g, function(m, a, w){ var s = w.toLowerCase(); return a + s.replace(/^(\s*)(\S)/, function(x, p, c){ return p + c.toUpperCase(); }); });
    if(u !== t) tn.textContent = u;
  });
}
function ivSideHtml(badgeCount){ return pxRailHtml(badgeCount); }
function ivSideMini(on){
  var de = document.documentElement;
  if(on === undefined) on = !de.classList.contains("iv-mini");
  de.classList.toggle("iv-mini", !!on);
  try{ localStorage.setItem("tec_iv_mini", on ? "1" : ""); }catch(e){}
}
try{ if(localStorage.getItem("tec_iv_mini")) document.documentElement.classList.add("iv-mini"); }catch(e){}
document.addEventListener("keydown", function(e){
  if(!ivTheme()) return;
  var a = document.activeElement, typing = a && (/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName) || a.isContentEditable);
  var host = document.querySelector(".jc-host"), sa = host && host.shadowRoot && host.shadowRoot.activeElement;
  if(sa && (/^(INPUT|TEXTAREA|SELECT)$/.test(sa.tagName) || sa.isContentEditable)) typing = true;
  if((e.ctrlKey || e.metaKey) && e.key === "Enter"){
    var m = document.querySelector(".modal .modal-foot .btn-primary:not([disabled])");
    if(m){ e.preventDefault(); m.click(); return; }
  }
  if(typing || e.ctrlKey || e.metaKey || e.altKey) return;
  if(e.key === "[" && ivDesk()){ e.preventDefault(); pxSideToggle(); return; }
  if((e.key === "j" || e.key === "k") && UI.view === "ros" && UI.selectedRo && !UI.modal && !document.querySelector(".modal")){
    var l = rlList(), i = -1; l.forEach(function(r, n){ if(r.id === UI.selectedRo) i = n; });
    var t = i < 0 ? null : l[e.key === "j" ? i + 1 : i - 1];
    if(t){ e.preventDefault(); UI.selectedRo = t.id; render(); window.scrollTo(0, 0); }
  }
});
var IV_CF = 0;
new MutationObserver(function(){
  if(IV_CF || !ivTheme()) return;
  IV_CF = requestAnimationFrame(function(){ IV_CF = 0; ivCaseFix(document.body); });
}).observe(document.documentElement, { childList: true, subtree: true });

function pzHeaderHtml(badgeCount){
  if(ivDesk()) return ivSideHtml(badgeCount);
  var cur = navCurrent(), allowed = {}, rp = runningPunch(), sh = openShift(), me = viewAsStaff(), wcNeed = 0;
  navPages().forEach(function(p){ allowed[p[0]] = p; });
  if(allowed.ros && allowed.rolist){ delete allowed.ros; if(cur && cur[0] === "ros") cur = allowed.rolist; }   /* the RO page lives inside the RO List */
  try{ wcNeed = wcNeedCount(); }catch(e){}
  var badge = { warranty: wcNeed, triage: UI.view !== "triage" ? (UI.tgBadgeN || 0) : 0, foreman: UI.view !== "foreman" ? (UI.fmBadgeN || 0) : 0 };
  var seen = {}, groups = PZ_GROUPS.map(function(g){ return [g[0], g[1].filter(function(k){ seen[k] = 1; return allowed[k]; })]; });
  var extra = Object.keys(allowed).filter(function(k){ return !seen[k]; });
  if(extra.length) groups.push(["More", extra]);
  groups = groups.filter(function(g){ return g[1].length; });
  var tabs = groups.map(function(g, gi){
    return (gi ? '<span class="pz-sep" aria-hidden="true"></span>' : '') + '<div class="pz-grp"><div class="pz-tabs">'
      + g[1].map(function(k){
          var p = allowed[k], on = p[0] === cur[0], b = badge[k] || 0;
          return '<button class="pz-tab'+(on ? ' on' : '')+'" data-action="nav" data-view="'+k+'"'+(on ? ' aria-current="page"' : '')+'>'
            + '<span class="pz-ti">'+(NAV_ICONS[k] || '')+'</span><span>'+esc(p[1])+'</span>'
            + (b ? '<span class="pz-bdg'+(k === "triage" ? ' tg-lt' : k === "foreman" ? ' fm-nb'+(UI.fmBadgeLate ? ' late' : '') : '')+'" title="'+(k === "foreman" ? esc(UI.fmBadgeTip || '') : b+(k === "triage" ? ' late on the yard' : ' to file or fix'))+'">'+b+'</span>' : '') + '</button>';
        }).join('') + '</div></div>';
  }).join('');
  var live = '';
  if(rp){
    var lro = getRO(rp.roId), lop = getOp(rp.roId, rp.opId);
    live = '<button class="pz-live" data-action="open-stop-punch" title="'+esc((lop ? lop.complaint + ' · ' : '') + 'click to stop the punch')+'"><i class="pz-pulse"></i><b class="mono">'+esc(lro ? (lro.shop ? 'Shop time' : roLabel(lro)) : 'RO')+'</b><span class="mono" data-live-hm="'+rp.start+'">'+fmtHM(Date.now() - new Date(rp.start))+'</span></button>';
  }
  var clock = sh
    ? '<button class="pz-clock in" data-action="shift-out" title="On the clock since '+esc(fmtTime(sh.in))+' \u00b7 click to clock out" aria-label="Clock out">'+PZ_CLK+'</button>'
    : '<button class="pz-clock out" data-action="shift-in" title="Clock in for the day" aria-label="Clock in">'+PZ_CLK+'</button>';
  return '<header class="pz-hdr" data-key="pz-hdr">'
    + '<div class="pz-top">'
    +   '<span class="pz-brand"><span class="pz-logo" aria-hidden="true"><svg viewBox="-110 -110 220 220"><circle r="14" fill="#22c55e"/><circle cx="44" r="9.5"/><circle cx="-44" r="9.5"/><circle cx="22" cy="38" r="9.5"/><circle cx="-22" cy="38" r="9.5"/><circle cx="22" cy="-38" r="9.5"/><circle cx="-22" cy="-38" r="9.5"/><circle cy="-84" r="7" class="o"/><circle cy="84" r="7" class="o"/><circle cx="73" cy="42" r="7" class="o"/><circle cx="-73" cy="42" r="7" class="o"/><circle cx="73" cy="-42" r="7" class="o"/><circle cx="-73" cy="-42" r="7" class="o"/></svg></span><b>Parsec</b></span>'
    +   '<span class="pz-sp"></span>'
    +   '<button class="pz-find" data-action="open-palette" title="Find an RO — number, VIN, unit, customer or part (Ctrl+K)">'+sfIcon(SF.search, 20)+'</button>'
    +   clock
    +   '<div class="hdr-bell pz-w">' + notifBtnHtml(badgeCount) + '</div>'
    +   '<div class="hdr-gear pz-w">' + settingsHtml() + '</div>'
    +   '<div class="hdr-me pz-me" data-key="hdr-me" title="'+esc((me ? me.name : (STATE.techName || 'Admin')) + ' \u00b7 ' + (me ? me.role : 'Every page'))+'">' + profileBtnHtml() + '</div>'
    + '</div>'
    + '<nav class="pz-row" aria-label="Pages">' + tabs + '</nav>'
    + '<div class="pz-lip" aria-hidden="true"></div>'
    + '</header>';
}
/* how much of the header stays on screen once the first line has scrolled away */
function hdrStuckH(){
  var pz = document.querySelector('.pz-hdr');
  if(pz && getComputedStyle(pz).position === 'fixed' && pz.getBoundingClientRect().width < window.innerWidth / 2) return 0;   /* the side menu — nothing across the top */
  if(pz){ var top = pz.querySelector('.pz-top'); return Math.round(pz.getBoundingClientRect().height - (top ? top.getBoundingClientRect().height : 0)); }
  var tb = document.querySelector('.topbar'); return tb ? Math.round(tb.getBoundingClientRect().height) : 0;
}
document.documentElement.classList.add('pz-rib');


/* ============================== CONSOLE ==============================
   A planning board, not a list of boxes: three headline cards, the week as a strip of days,
   the job on the clock, the team, and a side panel that follows the RO in focus. */
function cxDay(offset){ var d = new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate() + offset); return d; }
function cxArrow(attrs, label){
  return '<button class="cx-go" '+attrs+' title="'+esc(label)+'" aria-label="'+esc(label)+'">'+sfIcon(SF.arrowUR, 18)+'</button>';
}
function cxHM(ms){ var m = Math.round(Math.max(0, ms) / 60000); return { h: Math.floor(m / 60), m: m % 60 }; }
function cxBig(ms){ var t = cxHM(ms); return '<b>'+t.h+'</b><i>h</i><b>'+String(t.m).padStart(2, "0")+'</b><i>m</i>'; }
function cxSpark(vals, hiLast){
  var mx = Math.max.apply(null, vals.concat([1]));
  return '<span class="cx-spark" aria-hidden="true">' + vals.map(function(v, i){
    return '<i class="'+(hiLast && i === vals.length - 1 ? 'hi' : '')+'" style="--h:'+Math.max(6, Math.round(v / mx * 100))+'%;--i:'+i+'"></i>'; }).join('') + '</span>';
}
function cxRing(pct, size){
  var r = 20, c = 2 * Math.PI * r, p = Math.max(0, Math.min(1.5, pct || 0)), off = c * (1 - Math.min(1, p));
  return '<svg class="cx-ring" width="'+(size || 64)+'" height="'+(size || 64)+'" viewBox="0 0 48 48" aria-hidden="true">'
    + '<circle cx="24" cy="24" r="'+r+'" class="tr"/><circle cx="24" cy="24" r="'+r+'" class="fl" stroke-dasharray="'+c.toFixed(2)+'" stroke-dashoffset="'+off.toFixed(2)+'" transform="rotate(-90 24 24)"/></svg>';
}
function cxStatusFamily(st){
  var s = st.status || "";
  if(s === "Working") return "work";
  if(s.indexOf("Waiting") === 0) return s.indexOf("Parts") > 0 ? "parts" : (s.indexOf("Tech Support") > 0 ? "tech" : (s.indexOf("Customer") > 0 || s.indexOf("Approval") > 0 ? "cust" : "wait"));
  if(s.indexOf("Complete") === 0) return "done";
  return "hold";
}
function cxKpis(){
  var today = todayStr(), dc = dailyCalc(today);
  var week = [], i;
  for(i = -6; i <= 0; i++){ var d = todayStr(cxDay(i)); week.push({ d: d, ms: dailyCalc(d).burntMs || 0 }); }
  var eff = null; try{ eff = careerTotals(week[0].d, today).efficiency; }catch(e){}
  if(!(eff > 0) || !isFinite(eff)) eff = null;
  var effDays = 7;
  if(eff == null){ try{ eff = careerTotals(todayStr(cxDay(-29)), today).efficiency; effDays = 30; }catch(e){} if(!(eff > 0) || !isFinite(eff)) { eff = null; effDays = 7; } }   /* a quiet week shows the month */
  var open = STATE.ros.filter(function(ro){ return !roIsDone(ro); });
  var fam = { work:0, parts:0, cust:0, tech:0, wait:0, hold:0, done:0 };
  open.forEach(function(ro){ fam[cxStatusFamily(roStatus(ro))]++; });
  var waiting = fam.parts + fam.cust + fam.tech + fam.wait;
  var roIds = {}; dc.punches.forEach(function(p){ roIds[p.roId] = 1; });
  var nRo = Object.keys(roIds).length;
  var segs = ["work","parts","cust","tech","wait","hold","done"].filter(function(k){ return fam[k]; }).map(function(k){
    return '<i class="cx-seg s-'+k+'" style="flex:'+fam[k]+'" title="'+fam[k]+' '+({work:"working",parts:"waiting on parts",cust:"waiting on the customer",tech:"waiting on tech support",wait:"waiting",hold:"on hold",done:"done"})[k]+'"></i>'; }).join('');
  return '<div class="cx-kpis">'
    + '<div class="cx-k k-lime" style="--i:0"><div class="cx-k-top"><span class="cx-k-t">Punched<br>today</span>'+cxArrow('data-action="open-report" data-date="'+today+'"', "Today’s report")+'</div>'
    +   '<div class="cx-k-num">'+cxBig(dc.burntMs || 0)+'</div>'
    +   '<div class="cx-k-foot"><span class="cx-k-sub">'+dc.punches.length+' punch'+(dc.punches.length === 1 ? '' : 'es')+' · '+nRo+' RO'+(nRo === 1 ? '' : 's')+'</span>'+cxSpark(week.map(function(w){ return w.ms; }), true)+'</div></div>'
    + '<div class="cx-k k-paper" style="--i:1"><div class="cx-k-top"><span class="cx-k-t">Open repair<br>orders</span>'+cxArrow('data-action="nav" data-view="ros"', "Repair orders")+'</div>'
    +   '<div class="cx-k-num"><b>'+open.length+'</b></div>'
    +   '<div class="cx-k-foot"><span class="cx-k-sub">'+fam.work+' working · '+waiting+' waiting</span></div>'
    +   '<div class="cx-segs">'+segs+'</div></div>'
    + '<div class="cx-k k-ink" style="--i:2"><div class="cx-k-top"><span class="cx-k-t">Efficiency<br>'+effDays+' days</span>'+cxArrow('data-action="nav" data-view="career"', "Career")+'</div>'
    +   '<div class="cx-k-num"><b>'+(eff == null ? '—' : Math.round(eff * 100))+'</b>'+(eff == null ? '' : '<i>%</i>')+'</div>'
    +   '<div class="cx-k-foot"><span class="cx-k-sub">'+(eff == null ? 'No finished operations yet' : 'Quoted ÷ burnt hours')+'</span>'+cxRing(eff == null ? 0 : eff, 56)+'</div></div>'
    + '</div>';
}
function cxWeek(){
  var today = todayStr(), dc = dailyCalc(today), h = '', i;
  for(i = -4; i <= 3; i++){
    var d = cxDay(i), ds = todayStr(d), wd = d.toLocaleDateString(undefined, { weekday: "short" });
    if(i < 0){
      var ms = dailyCalc(ds).burntMs || 0, p = Math.min(1, ms / (8 * 3600000));
      h += '<button class="cx-day past" data-action="open-report" data-date="'+ds+'" style="--p:'+(p * 100).toFixed(1)+'%;--i:'+(i + 4)+'" title="'+esc(wd+' · '+fmtHM(ms)+' punched')+'">'
        + '<b>'+d.getDate()+'</b><small>'+esc(wd)+'</small></button>';
    } else if(i === 0){
      /* today: the open pill — hours punched, jobs, and the day's punches as dots on a 6am–6pm line */
      var marks = '', t0 = new Date(); t0.setHours(6,0,0,0); var span = 12 * 3600000;
      dc.punches.forEach(function(pu){
        var s = (new Date(pu.start) - t0) / span, e = ((pu.stop ? new Date(pu.stop) : new Date()) - t0) / span;
        s = Math.max(0, Math.min(1, s)); e = Math.max(s + .008, Math.min(1, e));
        marks += '<i class="'+(pu.stop ? '' : 'live')+'" style="left:'+(s * 100).toFixed(2)+'%;width:'+((e - s) * 100).toFixed(2)+'%"></i>';
      });
      var nowP = Math.max(0, Math.min(1, (Date.now() - t0) / span));
      h += '<div class="cx-day today" style="--i:4">'
        + '<span class="cx-td-n"><b>'+d.getDate()+'</b><small>'+esc(wd)+'</small></span>'
        + '<span class="cx-td-mid"><span class="cx-td-stats"><span><b class="mono">'+fmtHM(dc.burntMs || 0)+'</b><small>punched</small></span>'
        +   '<span><b class="mono">'+dc.punches.length+'</b><small>punches</small></span><span><b class="mono">'+fmtHM(dc.airMs || 0)+'</b><small>air</small></span></span>'
        +   '<span class="cx-td-line">'+marks+'<em style="left:'+(nowP * 100).toFixed(2)+'%"></em></span>'
        +   '<span class="cx-td-ticks"><small>6a</small><small>9a</small><small>12p</small><small>3p</small><small>6p</small></span></span>'
        + '</div>';
    } else {
      h += '<span class="cx-day future" style="--i:'+(i + 4)+'"><b>'+d.getDate()+'</b><small>'+esc(wd)+'</small></span>';
    }
  }
  return '<section class="cx-week"><div class="cx-h"><h2>This week</h2><span class="cx-h-s">'+esc(new Date().toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" }))+'</span></div>'
    + '<div class="cx-days">'+h+'</div></section>';
}
function cxMe(){ return viewAsStaff() || (STATE.techName ? staffForTech(STATE.techName) : null); }
function cxNow(){
  var rp = runningPunch();
  if(rp){
    var ro = getRO(rp.roId), op = getOp(rp.roId, rp.opId);
    var who = staffForTech(punchWho(rp)) || cxMe();
    var q = op ? (+op.quoted || 0) : 0, b = op ? (+op.burnt || 0) : 0;
    var pct = q > 0 ? Math.round(b / q * 100) : null;
    return '<section class="cx-now" data-key="cx-now">'
      + '<div class="cx-now-top">'+staffAvHtml(who || { name: punchWho(rp) || "Tech" }, "cx-av", "cn")
      +   '<span class="cx-now-who"><b>'+esc(who ? who.name : (punchWho(rp) || 'On the clock'))+'</b><small class="mono">'+esc(ro ? roLabel(ro) : '')+'</small></span>'
      +   cxArrow('data-action="goto-ro" data-ro="'+(ro ? ro.id : '')+'"', "Open the RO")+'</div>'
      + '<div class="cx-now-mid"><span class="cx-now-job"><b>'+esc(op ? op.complaint : 'Operation')+'</b><small>'+esc(rp.startReason || '')+(ro && ro.customerName ? ' · '+esc(ro.customerName) : '')+'</small></span>'
      +   '<span class="cx-now-clock mono" data-live-elapsed="'+rp.start+'">'+fmtHMS(Date.now() - new Date(rp.start))+'</span></div>'
      + '<div class="cx-prog'+(pct != null && pct > 100 ? ' over' : '')+'"><i style="width:'+Math.min(100, pct == null ? 4 : pct)+'%"><span>'+(pct == null ? '—' : pct + '%')+'</span></i></div>'
      + '<div class="cx-now-foot"><span>'+(q ? fmtDec(b)+' of '+fmtDec(q)+' quoted hours' : 'No quoted hours on this operation')+'</span>'
      +   '<span class="cx-now-btns"><button class="cx-pill" data-action="open-start-punch">'+sfIcon(SF.swap, 15)+'Switch</button>'
      +   '<button class="cx-pill dark" data-action="open-stop-punch">'+sfIcon(SF.stop, 14)+'Stop</button></span></div>'
      + '</section>';
  }
  var res = resumeTarget();
  return '<section class="cx-now idle" data-key="cx-now">'
    + '<div class="cx-now-top"><span class="cx-now-who"><b>Not on an operation</b><small>Pick one to start burning time</small></span></div>'
    + '<div class="cx-truck" aria-hidden="true">'+truckSvg()+'</div>'
    + '<div class="cx-now-foot">'
    + (res ? '<button class="cx-pill dark" data-action="resume-last">'+sfIcon(SF.play, 14)+'Resume '+esc(res.ro.roNumber)+'</button>' : '<span></span>')
    + (STATE.ros.length ? '<button class="cx-pill" data-action="open-start-punch">'+sfIcon(SF.play, 14)+'Start a punch</button>' : '<button class="cx-pill" data-action="load-sample-20">'+sfIcon(SF.sample, 14)+'Load samples</button>')
    + '</div></section>';
}
function cxTeam(){
  var techs = []; try{ techs = techLoad(); }catch(e){}
  var rows = '';
  if(techs.length){
    techs.slice(0, 6).forEach(function(t, i){
      var sf = t.sf || { name: t.name };
      var sub = t.run ? ((t.runRo ? t.runRo.roNumber + ' · ' : '') + 'on the clock') : (t.open + ' open RO' + (t.open === 1 ? '' : 's') + ' · ' + fmtDec(t.left) + ' h left');
      var go = t.run && t.runRo ? 'data-action="goto-ro" data-ro="'+t.runRo.id+'"' : 'data-action="nav" data-view="foreman"';
      rows += '<div class="cx-p '+(t.run ? 'live' : (t.open ? 'busy' : 'free'))+'" style="--i:'+i+'">'+staffAvHtml(sf, "cx-av", "tp")
        + '<span class="cx-p-t"><b>'+esc(t.name)+'</b><small>'+esc(sub)+'</small></span>'+cxArrow(go, t.run ? 'Open the RO' : 'Foreman board')+'</div>';
    });
  } else {
    sortedROs().filter(function(ro){ return !roIsDone(ro); }).slice(0, 5).forEach(function(ro, i){
      var st = roStatus(ro);
      rows += '<div class="cx-p '+(st.status === "Working" ? 'live' : 'busy')+'" style="--i:'+i+'"><span class="cx-av ini">'+esc(String(ro.roNumber).slice(-2))+'</span>'
        + '<span class="cx-p-t"><b>'+esc(ro.roNumber)+'</b><small>'+esc((ro.customerName || '') + ' · ' + st.status)+'</small></span>'+cxArrow('data-action="goto-ro" data-ro="'+ro.id+'"', 'Open the RO')+'</div>';
    });
  }
  return '<section class="cx-team"><div class="cx-h"><h2>'+(techs.length ? 'Team' : 'Open ROs')+'</h2>'
    + '<button class="cx-link" data-action="nav" data-view="'+(techs.length ? 'foreman' : 'ros')+'">See all</button></div>'
    + '<div class="cx-people">'+(rows || '<span class="hint">Nobody here yet.</span>')+'</div></section>';
}
function cxFocusRo(){
  var rp = runningPunch(); if(rp && getRO(rp.roId)) return getRO(rp.roId);
  if(UI.selectedRo && getRO(UI.selectedRo) && !roIsDone(getRO(UI.selectedRo))) return getRO(UI.selectedRo);
  return sortedROs().filter(function(ro){ return !roIsDone(ro); })[0] || null;
}
function cxCalendar(){
  var now = new Date(), y = now.getFullYear(), m = now.getMonth();
  var first = new Date(y, m, 1), days = new Date(y, m + 1, 0).getDate();
  var lead = (first.getDay() + 6) % 7, worked = {}, tStr = todayStr();
  allDates().forEach(function(d){ worked[d] = 1; });
  var cells = [];
  for(var i = 0; i < lead; i++) cells.push(null);
  for(var d = 1; d <= days; d++) cells.push(d);
  while(cells.length % 7) cells.push(null);
  var h = '', nWorked = 0;
  for(var r = 0; r < cells.length; r += 7){
    var c = 0;
    while(c < 7){
      var v = cells[r + c];
      var ds = v ? (y + '-' + String(m + 1).padStart(2, "0") + '-' + String(v).padStart(2, "0")) : null;
      if(v && worked[ds]){
        var run = [];
        while(c < 7 && cells[r + c] && worked[y + '-' + String(m + 1).padStart(2, "0") + '-' + String(cells[r + c]).padStart(2, "0")]){ run.push(cells[r + c]); c++; }
        nWorked += run.length;
        h += '<span class="cal-run" style="grid-column:'+(c - run.length + 1)+' / span '+run.length+'">' + run.map(function(x){
          var xs = y + '-' + String(m + 1).padStart(2, "0") + '-' + String(x).padStart(2, "0");
          return '<button data-action="open-report" data-date="'+xs+'" class="'+(xs === tStr ? 'td' : '')+'">'+x+'</button>'; }).join('') + '</span>';
      } else {
        h += '<span class="cal-d'+(ds === tStr ? ' td' : '')+(v ? '' : ' nil')+'" style="grid-column:'+(c + 1)+'">'+(v || '')+'</span>';
        c++;
      }
    }
  }
  return '<div class="cx-cal"><div class="cx-cal-h"><b>'+esc(now.toLocaleDateString(undefined, { month: "long" }))+'</b><small>'+nWorked+' day'+(nWorked === 1 ? '' : 's')+' worked</small></div>'
    + '<div class="cal-wd"><i>M</i><i>T</i><i>W</i><i>T</i><i>F</i><i>S</i><i>S</i></div><div class="cal-g">'+h+'</div></div>';
}
function cxSide(){
  var ro = cxFocusRo();
  var h = '<aside class="cx-side" data-key="cx-side">';
  if(!ro){
    return h + '<div class="cx-side-empty"><div class="cx-truck">'+truckSvg()+'</div><b>No open repair orders</b><span class="hint">Add one, or load the samples to look around.</span></div>' + cxCalendar() + '</aside>';
  }
  var I = roInfo(ro), st = I.st, tech = ro.assignedTech ? staffForTech(ro.assignedTech) : null;
  var burntMs = I.b * 3600000;
  h += '<div class="cx-s-head">' + staffAvHtml(tech || { name: ro.assignedTech || ro.customerName || "RO" }, "cx-av lg", "sd")
    + '<span class="cx-s-who"><b>'+esc(ro.assignedTech || 'Unassigned')+'</b><small><span class="mono">'+esc(roLabel(ro))+'</span><em class="st-'+cxStatusFamily(st)+'">'+esc(st.status.replace(/^Waiting – /, 'Waiting · ').replace(/^Complete – /, ''))+'</em></small></span>'
    + cxArrow('data-action="goto-ro" data-ro="'+ro.id+'"', 'Open the RO') + '</div>'
    + '<h3 class="cx-s-title">'+esc(I.complaint || 'Repair order')+'</h3>'
    + '<div class="cx-s-sub">'+esc([ro.customerName, ro.unitNumber ? 'Unit ' + ro.unitNumber : ''].filter(Boolean).join(' · '))+'</div>'
    + '<div class="cx-s-nums"><span><span class="cx-s-big">'+cxBig(burntMs)+'</span><small>Burnt so far</small></span>'
    +   '<span class="r"><span class="cx-s-big"><b>'+(I.eff == null ? '\u2014' : Math.round(I.eff * 100))+'</b>'+(I.eff == null ? '' : '<i>%</i>')+'</span><small>Efficiency</small></span></div>'
    + cxCalendar();
  return h + '</aside>';
}
/* a side-on Volvo-style tractor, drawn in SVG — used where a page has nothing live to show */
function truckSvg(){
  return '<svg class="truck-art" viewBox="0 0 320 130" fill="none" role="img" aria-label="Truck">'
    + '<defs><linearGradient id="tkB" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--tk-body-a, #f4f4f2)"/><stop offset="1" stop-color="var(--tk-body-b, #c9c9c5)"/></linearGradient>'
    + '<linearGradient id="tkG" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#9fb4c8"/><stop offset="1" stop-color="#3d4f63"/></linearGradient></defs>'
    + '<ellipse cx="170" cy="118" rx="150" ry="6" fill="currentColor" opacity=".12"/>'
    /* sleeper + cab */
    + '<path d="M96 30c0-6 5-11 11-11h72c9 0 15 3 20 10l20 28 34 7c9 2 15 9 15 18v16H96z" fill="url(#tkB)"/>'
    + '<path d="M182 24h-3c7 0 11 3 15 9l17 25h-29z" fill="url(#tkG)"/>'
    + '<path d="M150 26h22v30h-22z" fill="url(#tkG)" opacity=".85"/>'
    + '<path d="M96 70h172" stroke="currentColor" stroke-opacity=".18" stroke-width="2"/>'
    /* grille, bumper, light */
    + '<path d="M250 66h12c6 0 10 4 10 10v12h-22z" fill="#2b2f36"/>'
    + '<path d="M253 70h14M253 75h14M253 80h14" stroke="#7d8590" stroke-width="1.6"/>'
    + '<rect x="242" y="96" width="34" height="9" rx="3" fill="#2b2f36"/>'
    + '<path d="M268 60h8l-2 6h-8z" fill="var(--accent, #c6f432)"/>'
    /* chassis, tanks, fifth wheel, stack */
    + '<rect x="18" y="86" width="230" height="10" rx="3" fill="#2b2f36"/>'
    + '<rect x="122" y="88" width="44" height="16" rx="8" fill="#a9b0b8"/>'
    + '<rect x="40" y="80" width="40" height="7" rx="2" fill="#3a4049"/>'
    + '<rect x="100" y="8" width="5" height="40" rx="2" fill="#a9b0b8"/>'
    /* wheels */
    + [52, 84, 222].map(function(x){ return '<g transform="translate('+x+' 100)"><circle r="16" fill="#1d2025"/><circle r="9" fill="#9aa1aa"/><circle r="3.4" fill="#1d2025"/>'
        + '<path d="M0-9v4M0 5v4M-9 0h4M5 0h4" stroke="#1d2025" stroke-width="1.6"/></g>'; }).join('')
    + '</svg>';
}
function viewConsole(){
  var reminders = computeReminders();
  var openN = STATE.ros.filter(function(ro){ return !roIsDone(ro); }).length;
  var me = cxMe();
  var hi = new Date().getHours(), greet = hi < 12 ? 'Good morning' : (hi < 17 ? 'Good afternoon' : 'Good evening');
  var html = pageHeadHtml({ title: greet + (me ? ', ' + me.name.split(' ')[0] : ''),
    sub: esc(fmtDateLong(new Date().toISOString())) + (STATE.ros.length ? ' · ' + openN + ' open RO' + (openN === 1 ? '' : 's') : ''), acts: '' });
  if(reminders.escalated.length || reminders.soft.length){
    html += '<div class="cx-attn">';
    reminders.escalated.forEach(function(r){
      html += '<div class="reminder escalated"><span class="rem-ic">'+sfIcon(SF.warn, 17)+'</span><span class="rem-tx">'+esc(r.text)+'</span>'
        + (r.ro ? ' <button class="link-btn" data-action="goto-ro" data-ro="'+r.ro.id+'">Open RO</button>' : '')
        + (r.code === "M6" ? ' <button class="link-btn" data-action="dismiss-checklist-popup" data-ro="'+r.ro.id+'" title="Clear the flag so this stops being raised">Stop asking</button>' : '')
        + noteX(r) + '</div>';
    });
    reminders.soft.forEach(function(r){ html += '<div class="reminder"><span class="rem-ic">'+sfIcon(SF.bell, 17)+'</span><span class="rem-tx">'+esc(r.text)+'</span>'+(r.code === "BK" ? ' <button class="link-btn" data-action="export-json">Back up now</button>' : '')+noteX(r)+'</div>'; });
    html += '</div>';
  }
  try{ html += fmConsoleCard(); }catch(e){ console.error(e); }
  var dc = dailyCalc(todayStr());
  html += '<div class="cx">'
    + '<div class="cx-main">' + cxKpis() + cxWeek()
    +   '<div class="cx-duo">' + cxNow() + cxTeam() + '</div>' + cxStagesHtml()
    + '</div>'
    + cxSide()
    + '</div>';
  html += '<div class="bento cx-more">'
    + (dc.punches.length
      ? '<div class="card b-full b-bar"><h2>Today’s bar</h2>'+daybarHtml(dc)+'</div>'
      : '')
    + '<div class="b-punch">' + (punchDeckHtml() || '') + '</div>'
    + recentChangesHtml()
    + '</div>';
  return html;
}

/* ============================== charts ============================== */
/* Last 14 days as bars: punched time (accent) stacked on air time, one column per day. */
function hoursChartHtml(){
  var rows = [], mx = 0, i;
  for(i = 13; i >= 0; i--){
    var d = todayStr(cxDay(-i)), dc = dailyCalc(d);
    var r = { d: d, b: dc.burntMs || 0, a: dc.airMs || 0, dt: cxDay(-i) };
    rows.push(r); mx = Math.max(mx, r.b + r.a);
  }
  var top = Math.max(8, Math.ceil(mx / 3600000 / 2) * 2), H = top * 3600000;
  var wk = rows.slice(-7), wkB = 0, wkA = 0, nW = 0;
  wk.forEach(function(r){ wkB += r.b; wkA += r.a; if(r.b) nW++; });
  var cols = rows.map(function(r, i){
    var lbl = r.dt.toLocaleDateString(undefined, { weekday: "narrow" }), today = r.d === todayStr();
    return '<button class="hc-col'+(today ? ' td' : '')+'" data-action="open-report" data-date="'+r.d+'" style="--i:'+i+'" title="'+esc(r.dt.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" })+' · '+fmtHM(r.b)+' punched, '+fmtHM(r.a)+' air')+'">'
      + '<span class="hc-stack"><i class="hc-a" style="height:'+(r.a / H * 100).toFixed(2)+'%"></i><i class="hc-b" style="height:'+(r.b / H * 100).toFixed(2)+'%"></i></span>'
      + '<small>'+lbl+'</small><small class="hc-n">'+r.dt.getDate()+'</small></button>';
  }).join('');
  var grid = [0, .5, 1].map(function(f){ return '<i style="bottom:'+(f * 100)+'%"><em>'+Math.round(top * f)+'h</em></i>'; }).join('');
  return '<section class="hc card">'
    + '<div class="hc-side"><h2>Last 14 days</h2>'
    +   '<div class="hc-big">'+cxBig(wkB)+'</div><small>punched in the last 7 days</small>'
    +   '<div class="hc-mini"><span><b class="mono">'+fmtHM(wkA)+'</b><small>air time</small></span><span><b class="mono">'+(nW ? fmtHM(wkB / nW) : '0:00')+'</b><small>a working day</small></span></div>'
    +   '<div class="hc-leg"><span><i class="b"></i>Punched</span><span><i class="a"></i>Air</span></div></div>'
    + '<div class="hc-plot"><div class="hc-grid">'+grid+'</div><div class="hc-cols">'+cols+'</div></div>'
    + '</section>';
}
/* Efficiency day by day for the range on screen: a soft area line with 100% marked. */
function effTrendHtml(from, to){
  var days = allDates().filter(function(d){ return (!from || d >= from) && (!to || d <= to); }).slice(-30);
  var pts = [];
  days.forEach(function(d){ var t = null; try{ t = careerTotals(d, d).efficiency; }catch(e){} if(t > 0 && isFinite(t)) pts.push({ d: d, v: t }); });
  if(pts.length < 2) return '';
  /* one wild day (a tiny burn against a big quote) would flatten the rest: the scale tops out at 300% */
  var W = 720, H = 190, P = 26, mx = Math.min(3, Math.max(1.2, Math.max.apply(null, pts.map(function(p){ return p.v; })) * 1.1));
  var x = function(i){ return P + i * (W - 2 * P) / (pts.length - 1); }, y = function(v){ return H - P - (Math.min(v, mx) / mx) * (H - 2 * P); };
  var line = pts.map(function(p, i){ return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(p.v).toFixed(1); }).join(' ');
  var area = line + ' L' + x(pts.length - 1).toFixed(1) + ' ' + (H - P) + ' L' + x(0).toFixed(1) + ' ' + (H - P) + ' Z';
  var avg = (function(){ try{ return careerTotals(pts[0].d, pts[pts.length - 1].d).efficiency || 0; }catch(e){ return 0; } })(), best = pts.reduce(function(a, p){ return p.v > a.v ? p : a; }, pts[0]);
  var dots = pts.map(function(p, i){ return '<circle cx="'+x(i).toFixed(1)+'" cy="'+y(p.v).toFixed(1)+'" r="4" style="--i:'+i+'"><title>'+esc(p.d+' · '+Math.round(p.v * 100)+'%')+'</title></circle>'; }).join('');
  return '<section class="et card"><div class="et-h"><h2>Efficiency, day by day</h2>'
    + '<span class="et-stats"><span><b>'+Math.round(avg * 100)+'%</b><small>over these days</small></span><span><b>'+Math.round(best.v * 100)+'%</b><small>best day</small></span></span></div>'
    + '<svg class="et-svg" viewBox="0 0 '+W+' '+H+'" aria-label="Efficiency by day">'
    +   '<defs><linearGradient id="etFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".45"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>'
    +   '<line class="et-ref" x1="'+P+'" x2="'+(W - P)+'" y1="'+y(1).toFixed(1)+'" y2="'+y(1).toFixed(1)+'"/><text class="et-rt" x="'+(W - P)+'" y="'+(y(1) - 6).toFixed(1)+'" text-anchor="end">100%</text>'
    +   '<path class="et-area" d="'+area+'" fill="url(#etFill)"/><path class="et-line" d="'+line+'" pathLength="1"/>' + dots
    + '</svg></section>';
}

/* ============================== realistic portraits ==============================
   Demo staff wear a real stock portrait (randomuser.me), loaded by the browser. Offline, or
   if the shop network blocks it, the drawn portrait underneath simply stays. An uploaded
   photo always wins. */
var PHOTO_FAIL = false;
var DEMO_PHOTO = { "Mike Rodriguez":"men/32", "Dana Kowalski":"women/44", "Luis Martinez":"men/75", "Priya Shah":"women/65",
  "Frank Delaney":"men/86", "Tom Brandt":"men/52", "Jenna Cho":"women/90", "Derek Washington":"men/22", "Sofia Alvarez":"women/29", "Ben Okafor":"men/46" };
var PHOTO_MAP = null, PHOTO_SIG = "";
function staffPhotoUrl(sf){
  if(!sf || PHOTO_FAIL || !sf.av) return "";
  var list = staffList(), sig = list.map(function(x){ return x.id; }).join(",");
  if(!PHOTO_MAP || sig !== PHOTO_SIG){
    PHOTO_MAP = {}; PHOTO_SIG = sig; var used = {};
    list.forEach(function(x){ if(DEMO_PHOTO[x.name]){ PHOTO_MAP[x.id] = DEMO_PHOTO[x.name]; used[DEMO_PHOTO[x.name]] = 1; } });
    list.forEach(function(x){
      if(PHOTO_MAP[x.id] || !x.av) return;
      var g = x.av.f ? "women" : "men", n = 0, s = String(x.name || x.id);
      for(var i = 0; i < s.length; i++) n = (n * 31 + s.charCodeAt(i)) % 9973;
      var k = n % 99; while(used[g + "/" + k]) k = (k + 7) % 99;
      PHOTO_MAP[x.id] = g + "/" + k; used[g + "/" + k] = 1;
    });
  }
  var key = PHOTO_MAP[sf.id] || DEMO_PHOTO[sf.name];
  return key ? "https://randomuser.me/api/portraits/" + key + ".jpg" : "";
}
/* the island stays shut after you pick a page until the pointer leaves it */
document.addEventListener("mouseover", function(e){
  if(!UI.diShut || (e.target.closest && e.target.closest(".island"))) return;
  UI.diShut = false; var isl = document.querySelector(".island"); if(isl) isl.classList.remove("shut");
}, { passive: true });
/* keyboard users open the island by tabbing into it; a mouse pick never leaves it stuck open */
var KBD_NAV = false;
document.addEventListener("keydown", function(e){ if(e.key === "Tab") KBD_NAV = true; }, true);
document.addEventListener("mousedown", function(){ KBD_NAV = false; }, true);
document.addEventListener("focusin", function(e){
  if(KBD_NAV && e.target.closest && e.target.closest(".island") && !UI.navOpen){ UI.navOpen = true; UI.diShut = false; render(); }
});
document.addEventListener("focusout", function(e){
  if(!UI.navOpen || !(e.target.closest && e.target.closest(".island"))) return;
  var to = e.relatedTarget;
  if(to && to.closest && to.closest(".island")) return;
  setTimeout(function(){ if(UI.navOpen && !(document.activeElement && document.activeElement.closest && document.activeElement.closest(".island"))){ UI.navOpen = false; render(); } }, 0);
});
window.__tecPhotoFail = function(img){
  PHOTO_FAIL = true;
  document.documentElement.classList.add("no-photos");
  try{ img.remove(); }catch(e){}
};


/* shop time: three operations you clock on like any job */
function shopStartRowHtml(){
  var rp = runningPunch(), r = shopRo();
  return '<div class="shop-row"><span class="shop-row-t">'+sfIcon(SF.kit, 16)+'Shop time</span>' + r.operations.filter(function(o){ return !o.declined; }).map(function(o){
    var on = !!(rp && rp.opId === o.id);
    return '<button class="shop-chip'+(on ? ' on' : '')+'" data-action="'+(on ? 'open-stop-punch' : 'shop-start')+'" data-op="'+o.id+'" title="'+(on ? 'On the clock \u2014 click to stop' : 'Clock on: ' + esc(o.complaint))+'">'
      + (on ? '<i class="shop-live"></i>' : sfIcon(SF.play, 12)) + esc(o.complaint) + '</button>'; }).join('') + '</div>';
}
function punchDeckHtml(){
  var cands = punchCandidates();
  if(!cands.length) return "";
  var rp = runningPunch();
  var res = resumeTarget();

  var h = '<div class="card"><h2>Punch On <span class="eyebrow">most recent first</span></h2>';

  if(res && !rp){
    h += '<button class="btn btn-primary resume-btn" data-action="resume-last">'
      + '<span>↻ Resume</span> <span class="resume-what">'+esc(roTag(res.ro))+' — '+esc(res.op.complaint)+'</span>'
      + '<span class="resume-reason">'+esc(res.reason)+'</span></button>';
  }

  h += '<div class="punch-deck">';
  cands.slice(0,8).forEach(function(c){
    var s = typeof c.st==="string" ? c.st : c.st.status;
    var when = c.last ? "last "+fmtDate(new Date(c.last).toISOString())+" "+fmtTime(new Date(c.last).toISOString()) : "not started";
    var cls = "punch-tile" + (c.running ? " running" : "");
    var action = c.running ? "open-stop-punch" : "open-start-punch";
    h += '<button class="'+cls+'" data-action="'+action+'" data-ro="'+c.ro.id+'" data-op="'+c.op.id+'"'
      + ' title="'+esc(c.op.complaint)+'"'
      + '>'
      + '<span class="pt-ro">RO '+esc(c.ro.roNumber)+'</span>'
      + '<span class="pt-op">'+esc(c.op.complaint)+'</span>'
      + '<span class="pt-foot">'+(c.running ? '<b class="pt-live">■ Stop punch</b>' : '<span class="pill '+statusTone(c.st)+'"><span class="dot"></span>'+esc(s)+'</span>')+'</span>'
      + '<span class="pt-when">'+esc(when)+'</span>'
      + '</button>';
  });
  h += '</div>' + shopStartRowHtml() + '</div>';
  return h;
}

function storageCardHtml(){
  var L = storageLabel();
  var h = '<div class="set-data"><div class="app-menu-lbl">Your data</div>';
  /* The save indicator used to sit in the top bar as a dot you had to hover. It lives
     here now, with room to say the status in words. It only appears once there is a
     folder to save into \u2014 without one the lines below already tell that story, and
     two versions of it in the same card just say the same thing twice. */
  if(FS.status === "connected"){
    h += '<button class="save-state '+L.dot+'" id="storage-chip" data-action="storage" '
      + 'title="Click to change your data folder" aria-label="'+esc(L.head)+'">'
      + '<span class="sync-dot '+L.dot+'" id="sync-dot"></span>'
      + '<span class="save-state-tx"><b id="sync-pop-head">'+esc(L.head)+'</b>'
      +   '<span id="sync-pop-body">'+esc(L.body)+'</span></span>'
      + '</button>';
  }
  if(FS.status==="connected"){
    h += '<div class="storage-line"><span class="storage-badge ok">●</span><div><b>'+esc(FS.dirName)+'</b>'
      + '<div class="hint">Each RO saves to its own folder in <span class="mono">Parsec Data/ROs/</span> — its Repair Order page plus an <span class="mono">Attachments</span> folder. Shop-wide data goes to <span class="mono">Parsec Data/Shop/Shop.html</span>, plus a dated copy in <span class="mono">Parsec Data/Backups/</span> once a day.</div></div></div>'
      + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">'
      + '<button class="ib btn btn-sm" data-action="save-now" title="Save now" aria-label="Save now">'+IC.save+'</button>'
      + '<button class="ib btn btn-sm" data-action="export-json" title="Save a backup copy" aria-label="Save a backup copy">'+IC.backup+'</button>'
      + '<button class="ib btn btn-sm" data-action="open-restore" title="Restore from a backup" aria-label="Restore from a backup">'+IC.restore+'</button>'
      + '<button class="ib btn btn-sm" data-action="storage" title="Change the data folder" aria-label="Change the data folder">'+IC.folder+'</button>'
      + '</div>';
  } else if(FS.status==="needs-permission"){
    h += '<div class="storage-line"><span class="storage-badge warn">●</span><div><b>Folder needs reconnecting</b>'
      + '<div class="hint">Chrome asks permission once each time you open the app. Your work is safe in this browser in the meantime.</div></div></div>'
      + '<div style="margin-top:12px;"><button class="ib btn btn-primary btn-sm" data-action="storage" title="Reconnect “'+esc(FS.dirName||"folder")+'”" aria-label="Reconnect your data folder">'+IC.folderSync+'</button></div>';
  } else if(FS.status==="unsupported"){
    h += '<div class="storage-line"><span class="storage-badge warn">●</span><div><b>Saving in this browser only</b>'
      + '<div class="hint">Folder saving needs Chrome or Edge on a desktop. Everything still works here — export a backup regularly.</div></div></div>'
      + '<div style="margin-top:12px;"><button class="ib btn btn-sm" data-action="export-json" title="Export a backup copy" aria-label="Export a backup copy">'+IC.backup+'</button></div>';
  } else {
    h += '<div class="storage-line"><span class="storage-badge warn">●</span><div><b>No folder connected yet</b>'
      + '<div class="hint">Pick a folder on your computer and this app keeps all its data there — a folder per RO with its Repair Order page and attachments — yours, offline, no cloud.</div></div></div>'
      + '<div style="margin-top:12px;"><button class="ib btn btn-primary btn-sm" data-action="storage" title="Connect your data folder" aria-label="Connect your data folder">'+IC.folder+'</button></div>';
  }
  h += '<div class="data-tools"><span class="eyebrow">Phone</span><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:7px;">'
    +   '<button class="btn btn-sm btn-primary" data-action="phone-sync" data-mode="send" title="Show QR codes for Parsec Mobile">Send to phone</button>'
    +   '<button class="btn btn-sm" data-action="phone-sync" data-mode="get" title="Read Parsec Mobile\u2019s QR codes with the webcam">Get from phone</button></div>'
    +   '<div class="hint" style="margin-top:6px;">QR codes between this computer and Parsec Mobile \u2014 no network.</div></div>';
  h += '<div class="data-tools"><span class="eyebrow">Shop</span><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:7px;">'
    +   '<label for="set-labor" class="hint" style="margin:0">Labor rate</label><input id="set-labor" data-bind="labor-rate" class="mono" inputmode="decimal" style="width:90px;padding:5px 8px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--ink);font:inherit" value="'+esc(String(laborRate()))+'"><span class="hint" style="margin:0">$ per hour</span></div>'
    +   '<div class="hint" style="margin-top:6px;">Used for the labor cost on every operation.</div></div>';
  h += '<div class="build-stamp mono" title="Which build of the page this is">'+esc(BUILD)+'</div>';
  h += '<div class="data-tools">'
    + '<span class="eyebrow">Test data</span>'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:7px;">'
    +   '<button class="btn btn-sm btn-primary" data-action="sample-25" title="Generate 25 sample repair orders">'+IC.sample+'<span>Generate 25 sample ROs</span></button>'
    +   '<button class="ib btn btn-sm btn-danger" data-action="clear-sample" title="Clear all data" aria-label="Clear all data">'+IC.trash+'</button>'
    + '</div>'
    + '<div class="hint" style="margin-top:6px;">25 scenarios: a live clock, partial diag and repair time, parts on order and backorder, holds, approval, completed operations that become kits, and repeat operations for parts suggestions. Running it again replaces the last set. Undo with Ctrl+Z.</div>'
    + '</div>';
  h += '</div><div class="app-menu-sep"></div>';
  return h;
}

/* One header for every page: title (and a line under it) on the left, the page's own
   search or filters in the middle, its actions on the right. Same height everywhere,
   so every page's content starts at the same line. */
function pageHeadHtml(o){
  return '<header class="pg-head">'
    + '<div class="pg-title"><h1>'+esc(o.title)+'</h1>'+(o.sub ? '<div class="pg-sub">'+o.sub+'</div>' : '')+'</div>'
    + '<div class="pg-mid">'+(o.mid || '')+'</div>'
    + '<div class="pg-acts">'+(o.acts || '')+'</div>'
    + '</header>';
}

function statTile(label, val, unit){
  return '<div class="stat-tile"><span class="eyebrow">'+esc(label)+'</span><div class="val">'+val+(unit?' <span class="unit">'+unit+'</span>':'')+'</div></div>';
}

function daybarHtml(dc, opts){
  opts = opts || {};
  /* The frame is drawn even before the first punch, so the clock scale is always
     there to read against — an empty day is a bar of empty, not a line of text. */
  var hasPunches = dc.blocks.length > 0;
  var start, end;
  if(hasPunches){
    start = new Date(dc.firstStart); end = new Date(dc.lastStop);
  } else {
    start = new Date(); start.setHours(7,0,0,0);
    end = new Date(); end.setHours(16,0,0,0);
    var nowF = new Date();
    if(nowF > end) end = nowF;
    if(nowF < start){ start = new Date(nowF.getTime() - 60*60000); end = new Date(nowF.getTime() + 60*60000); }
  }
  var total = Math.max(end - start, 60000);

  var h = '<div class="daybar"><div class="segwrap"><div class="seg" data-t0="'+start.getTime()+'" data-tt="'+total+'">';
  var segStart = start, segTotal = total;
  if(!hasPunches){
    h += '<span class="seg-block blk-empty" style="flex:1 0 auto" title="Nothing punched yet today"></span>';
  }
  var accPct = 0, subFlags = "";
  function subFlag(b, at0){
    var sub = airNoteFor(b); if(!sub) return "";
    return '<span class="air-flag" style="left:'+at0.toFixed(3)+'%" data-action="seg-air" data-day="'+dc.date+'" data-at="'+b.at+'" data-ms="'+b.ms+'" data-label="'+esc(b.label||"")+'" title="'+esc(sub)+'">'
      + '<i class="af-stem"></i><b class="af-f"><span class="af-ic" aria-hidden="true">\u270e</span><span class="af-tx">'+esc(sub)+'</span></b></span>';
  }
  dc.blocks.forEach(function(b){
    /* exact share of the span: the block must start and end where the axis says it does,
       so no minimum width and no content-sized flex basis that would push later blocks right */
    var pct = Math.max(0, (b.ms / total) * 100);
    if(b.ms <= 0 && b.kind !== "seam") return;
    var at0 = accPct; accPct += pct;
    if(!b.edge && (b.kind === "air" || b.kind === "shop" || (b.kind === "lunch" && !b.shiftGap))) subFlags += subFlag(b, at0);
    if(b.kind === "punch"){
      var ro = getRO(b.punch.roId), op = ro ? getOp(ro.id, b.punch.opId) : null;
      var shopP = isShopPunch(b.punch);
      var opN = (ro && op && !shopP) ? (ro.operations || []).indexOf(op) + 1 : 0;
      h += '<button class="seg-block blk-punch'+(shopP?" blk-shopop":"")+(b.punch.stop?"":" live")+(UI.segPick===b.punch.id?" sel":"")+(opts.ro && b.punch.roId!==opts.ro?" other-ro":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;"'
         + ' data-action="seg-pick" data-punch="'+b.punch.id+'"'
         + ' title="'+(shopP ? 'Shop time' : 'RO '+(ro?esc(ro.roNumber):"?")+(opN ? ' \u00b7 Op '+opN : ''))+' \u2014 '+(op?esc(op.complaint):"?")+', '+fmtHM(b.ms)+' \u2014 click to edit">'
         + (pct > 9 ? (shopP ? (op?esc(op.complaint):"Shop") : (ro?'<span class="seg-ro">'+esc(ro.roNumber)+'</span>'+(opN && pct > 12 ? '<small class="seg-opn">Op '+opN+'</small>' : ''):"")) : "")
         + (UI.segPick===b.punch.id ? '<span class="seg-hd l" data-edge="s" title="Drag to change the start" aria-hidden="true"></span>'+(b.punch.stop?'<span class="seg-hd r" data-edge="e" title="Drag to change the stop" aria-hidden="true"></span>':'') : '')
         + '</button>';
    } else if(b.kind === "off"){
      h += '<div class="seg-block blk-off'+(b.label?' lab':'')+'" style="flex:0 0 '+pct.toFixed(3)+'%;" title="'+(b.label ? esc(b.label)+' \u2014 clocked out' : 'Off the clock')+' \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+'">'+(b.label && pct > 8 ? esc(b.label) : '')+'</div>';
    } else if(b.kind === "lunch" && b.shiftGap){
      h += '<div class="seg-block blk-lunch" style="flex:0 0 '+pct.toFixed(3)+'%;" title="Lunch \u2014 clocked out '+fmtClockHM(new Date(b.at))+' to '+fmtClockHM(new Date(new Date(b.at).getTime()+b.ms))+', '+fmtHM(b.ms)+'">'+(pct > 5 ? 'Lunch' : '')+'</div>';
    } else if(b.edge){
      var eLab = b.edge === "in" ? "Clocked in" : "Off the last operation";
      h += '<button class="seg-block blk-air blk-edge'+(UI.segShift && UI.segShift.day===dc.date && UI.segShift.edge===b.edge && UI.segShift.id===b.shiftId?" sel":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;"'
         + ' data-action="seg-shift" data-day="'+dc.date+'" data-edge="'+b.edge+'" data-id="'+b.shiftId+'"'
         + ' title="'+eLab+' \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+' on the clock, off an operation \u2014 click to edit">'
         + (pct > 9 ? (b.edge === "in" ? "Clocked in" : "Air") : "") + '</button>';
    } else if(b.kind === "seam"){
      h += '<div class="seg-block blk-seam" style="flex:0 0 '+pct.toFixed(3)+'%;" title="Operation switch \u2014 '+Math.round(b.ms/1000)+'s"></div>';
    } else if(b.kind === "empty"){
      h += '<button class="seg-block blk-empty'+(emptyPicked(dc, b)?" sel":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;" data-action="seg-empty" data-day="'+dc.date+'" data-at="'+b.at+'" data-ms="'+b.ms+'"'
         + ' title="Empty \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+' \u2014 click to fill or restore"></button>';
    } else if(b.kind === "shop"){
      h += '<button class="seg-block blk-shop'+(airPicked(dc, b)?" sel":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;"'
         + ' data-action="seg-air" data-day="'+dc.date+'" data-at="'+b.at+'" data-ms="'+b.ms+'" data-label="'+esc(b.label)+'"'
         + ' title="'+esc(b.label)+' \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+' \u2014 click to edit">'
         + (pct > 8 ? esc(b.label) : "") + '</button>';
    } else if(b.kind === "lunch"){
      var lnN = airNoteFor(b);
      h += '<button class="seg-block blk-lunch'+(airPicked(dc, b)?" sel":"")+(lnN?" has-note":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;"'
         + ' data-action="seg-air" data-day="'+dc.date+'" data-at="'+b.at+'" data-ms="'+b.ms+'" data-label="Lunch"'
         + ' title="Lunch \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+'\nClick to edit">'
         + (pct > 6 ? 'Lunch' : "") + '</button>';
    } else {
      var airLab = 'Air time', airN = airNoteFor(b);   /* just "Air" - the reason is the note, shown on hover */
      h += '<button class="seg-block blk-air'+(airPicked(dc, b)?" sel":"")+(airN?" has-note":"")+'" style="flex:0 0 '+pct.toFixed(3)+'%;"'
         + ' data-action="seg-air" data-day="'+dc.date+'" data-at="'+b.at+'" data-ms="'+b.ms+'" data-label="'+esc(b.label||"")+'"'
         + ' title="'+esc((airN ? airN + '\n' : '') + airLab+' \u2014 '+fmtClockHM(new Date(b.at))+', '+fmtHM(b.ms)+'\nClick to edit')+'">'
         + (pct > 9 ? 'Air' : "") + '</button>';
    }
  });
  if(subFlags) h = h.replace('<div class="daybar"><div class="segwrap">', '<div class="daybar"><div class="segwrap has-sub">');
  h += '</div>' + shiftMarksHtml(dc, start, total) + subFlags + '</div>';   // close .seg (flags sit over it) and .segwrap so the axis can span the full width

  /* Hour marks with the label, quarter-hour marks without — so the bar reads as a
     clock rather than a proportion you have to work out. */
  /* Label step follows the span: a full shift gets hour labels, a short one gets
     quarters, so the axis is never blank. Minor marks stay at 15 minutes. */
  /* Hours (tall, labelled HH:00) and minutes (short marks) — the minute step follows the span
     so the marks never smear: 1 min under an hour, 5 min up to 10 h, 15 min beyond. */
  var spanMin = total / 60000;
  var labelEvery = spanMin >= 240 ? 60 : (spanMin >= 90 ? 30 : (spanMin >= 30 ? 15 : 5));
  var minorStep = spanMin <= 60 ? 1 : (spanMin <= 600 ? 5 : 15);
  h += '<div class="dayaxis">';
  var q = new Date(start);
  q.setSeconds(0, 0);
  q.setMinutes(Math.ceil((q.getMinutes() + (start.getSeconds() || start.getMilliseconds() ? 1 : 0)) / minorStep) * minorStep);
  var guard = 0, labelled = 0;
  while(q <= end && guard++ < 900){
    var at = ((q - start) / total) * 100;
    var mins = q.getMinutes();
    var cls = mins === 0 ? " hour" : (mins % 30 === 0 ? " half" : (mins % 15 === 0 ? " quarter" : (mins % 5 === 0 ? " five" : "")));
    var isLabel = (mins % labelEvery) === 0;
    h += '<span class="tickmark'+cls+'" style="left:'+at.toFixed(3)+'%"></span>';
    if(isLabel){ h += '<span class="ticklab mono'+(mins===0?" hr":"")+(at < 2.5 ? " edge-l" : (at > 97.5 ? " edge-r" : ""))+'" style="left:'+at.toFixed(3)+'%">'+fmtClockHM(q)+'</span>'; labelled++; }
    q = new Date(q.getTime() + minorStep*60000);
  }
  // a span too short to cross a boundary still deserves its ends labelled
  if(!labelled){
    h += '<span class="tickmark hour" style="left:0%"></span><span class="ticklab mono edge-l" style="left:0%">'+fmtClockHM(start)+'</span>'
       + '<span class="tickmark hour" style="left:100%"></span><span class="ticklab mono edge-r" style="left:100%">'+fmtClockHM(end)+'</span>';
  }
  h += '</div>';

  h += segPopHtml(segStart, segTotal, dc) + airPopHtml(segStart, segTotal, dc) + emptyPopHtml(segStart, segTotal, dc) + shiftPopHtml(segStart, segTotal, dc) + '<div class="daybar-legend">'
    + (opts.ro ? '<span><i class="legend-sw" style="background:var(--status-working);"></i>This RO</span><span><i class="legend-sw" style="background:var(--status-working);opacity:.42"></i>Other ROs</span>'
               : '<span><i class="legend-sw" style="background:var(--accent);"></i>Punched on an operation</span>')
    + '<span><i class="legend-sw legend-air"></i>Air time \u2014 punched out, until the next operation or lunch</span>'
    + '<span><i class="legend-sw" style="background:var(--lunch-color);"></i>Lunch</span>'
    + '<span><i class="legend-sw" style="background:var(--shop-color);"></i>Shop time \u2014 maintenance, training, cleaning</span>'
    + '<span><i class="legend-sw legend-seam"></i>Operation switch \u2014 under 11 s</span>'
    + (dc.offMs ? '<span><i class="legend-sw legend-off"></i>Off the clock</span>' : '')
    + (dc.shifts && dc.shifts.length ? '<span class="hint mono">Clocked '+fmtHM(dc.clockedMs)+(dc.onClock?' \u00b7 still on the clock':'')+'</span>' : '')
    + (hasPunches ? '' : '<span class="hint mono">Nothing punched yet today</span>')
    + '</div></div>';
  return h;
}
/* Clicking a block opens a card under the bar rather than a modal — the bar stays
   visible, so you can see what you are about to change. */
function segPopHtml(winStart, winTotal, dc){
  var sp = UI.segPick;
  if(!sp) return "";
  var p = STATE.punches.filter(function(x){ return x.id===sp; })[0];
  if(!p){ UI.segPick = null; return ""; }
  if(dc && localDay(p.start) !== dc.date) return "";
  var ro = getRO(p.roId), op = ro ? getOp(ro.id, p.opId) : null;
  var ms = (p.stop ? new Date(p.stop) : new Date()) - new Date(p.start);
  var mid = (new Date(p.start).getTime() + ms/2 - winStart.getTime()) / winTotal * 100;
  mid = Math.min(Math.max(mid, 14), 86);
  var nud = function(edge, vals){
    return '<div class="se-nud">' + vals.map(function(d){
      return '<button type="button" class="btn btn-sm" data-action="seg-nudge" data-punch="'+p.id+'" data-edge="'+edge+'" data-d="'+d+'">'+(d>0?"+":"−")+Math.abs(d)+'</button>';
    }).join("") + '</div>';
  };
  var hm = function(iso){ var d = new Date(iso); return String(d.getHours()).padStart(2,"0")+":"+String(d.getMinutes()).padStart(2,"0"); };
  var g = segGaps(dc, p);
  var gapRow = function(x, side){
    if(!x) return "";
    var from = new Date(x.at), to = new Date(x.at + x.ms);
    var nb = x.nb ? getRO(x.nb.roId) : null;
    var selfLab = side === "b" ? "Extend this back to "+fmtClockHM(from) : "Extend this on to "+fmtClockHM(to);
    var nbLab = x.nb ? (side === "b" ? "Extend "+(nb?esc(nb.roNumber):"?")+" forward to "+fmtClockHM(to) : "Extend "+(nb?esc(nb.roNumber):"?")+" back to "+fmtClockHM(from)) : "";
    return '<div class="se-gap"><span class="se-when mono"><span class="sp-kind '+(x.kind==="empty"?"se-k-empty":"air")+'">'+(x.kind==="empty"?"Empty":"Air")+'</span>'+fmtClockHM(from)+' – '+fmtClockHM(to)+' · '+fmtHM(x.ms)+'</span>'
      + '<button type="button" class="btn btn-sm btn-primary" data-action="seg-extend" data-punch="'+p.id+'" data-side="'+side+'" data-who="self">'+selfLab+'</button>'
      + (x.nb ? '<button type="button" class="btn btn-sm" data-action="seg-extend" data-punch="'+p.id+'" data-side="'+side+'" data-who="nb">'+nbLab+'</button>' : '')
      + '</div>';
  };
  return '<div class="segpop segedit" style="left:'+mid.toFixed(2)+'%" role="dialog" aria-label="Edit segment">'
    + '<div class="sp-top"><span class="sp-kind punch">Punch</span>'
    +   '<span class="se-what"><b class="mono">'+esc(ro?ro.roNumber:"?")+'</b> — '+esc(op?op.complaint:"?")+'</span>'
    +   '<span class="sp-when mono se-when-ed"><input type="time" step="60" class="se-time" data-segtime="s" data-punch="'+p.id+'" value="'+hm(p.start)+'" aria-label="Start time" title="Start time">'
    +     '<span>–</span>'+(p.stop ? '<input type="time" step="60" class="se-time" data-segtime="e" data-punch="'+p.id+'" value="'+hm(p.stop)+'" aria-label="Stop time" title="Stop time">' : '<span>running</span>')
    +     '<span class="se-dur">'+fmtHM(ms)+'</span></span>'
    +   '<span class="sp-gap"></span>'
    +   '<button class="ib btn btn-sm" data-action="open-edit-punch" data-punch="'+p.id+'" title="Reasons and notes" aria-label="Reasons and notes">'+IC.pencil+'</button>'
    +   '<button class="ib btn btn-sm btn-danger" data-action="seg-delete" data-punch="'+p.id+'" title="Delete punch" aria-label="Delete punch">'+IC.trash+'</button>'
    +   '<button class="btn btn-sm btn-primary" data-action="seg-close">Done</button>'
    + '</div>'
    + (isShopPunch(p) ? '' : '<div class="se-reasons">'
    +   '<label><span class="se-lb">Start reason</span><select data-segreason="start" data-punch="'+p.id+'">'+(START_REASONS.indexOf(p.startReason)<0 && p.startReason ? [p.startReason] : []).concat(START_REASONS).map(function(r){ return '<option value="'+esc(r)+'"'+(r===p.startReason?' selected':'')+'>'+esc(r)+'</option>'; }).join('')+'</select></label>'
    +   (p.stop ? '<label><span class="se-lb">Stop reason</span><select data-segreason="stop" data-punch="'+p.id+'">'+editStopReasonOptions(p)+'</select></label>'
              : '<label><span class="se-lb">Stop reason</span><select disabled><option>Still running</option></select></label>')
    + '</div>')
    + (p.stop ? '<div class="se-rows"><div class="se-row"><span class="se-lb">Move</span><span class="se-sub">keeps length</span>'+nud("m",[-15,-5,5,15])+'</div></div>' : '')
    + ((g.before || g.after) ? '<div class="se-sect"><div class="se-h">Empty time next to this segment</div>'+gapRow(g.before,"b")+gapRow(g.after,"a")+'</div>' : '')
    + (UI.segMsg ? '<div class="se-msgrow"><span class="se-msg mono" role="status">'+esc(UI.segMsg)+'</span></div>' : '')
    + '</div>';
}

/* ---------- quick time adjust for a selected punch ---------- */
var SEG_SNAP = 5, SEG_MIN = 60000;
function segBounds(p){
  var st = new Date(p.start).getTime(), lo = -Infinity, hi = Infinity;
  STATE.punches.forEach(function(x){
    if(x.id === p.id) return;
    var xs = new Date(x.start).getTime(), xe = x.stop ? new Date(x.stop).getTime() : Date.now();
    if(xs < st) lo = Math.max(lo, xe); else hi = Math.min(hi, xs);
  });
  if(!p.stop) hi = Math.min(hi, Date.now());
  return { lo: lo, hi: hi };
}
/* Apply new start/stop (ms) to a punch, held between its neighbours. No undo push here. */
function segApply(p, ns, ne, noTrim){
  var bd = segBounds(p);
  ns = Math.max(bd.lo, ns);
  if(p.stop){ ne = Math.min(bd.hi, ne); if(ne - ns < SEG_MIN){ return false; } }
  else { if(ns > Date.now() - SEG_MIN) return false; }
  if(!p.edited){ p.edited = true; p.originalStart = p.start; p.originalStop = p.stop; }
  p.editedAt = nowIso();
  p.start = new Date(ns).toISOString();
  if(p.stop) p.stop = new Date(ne).toISOString();
  if(!noTrim) segTrimHoles(ns, p.stop ? ne : Date.now());
  scheduleSave(true);
  return true;
}
/* A punch that now covers part of an empty block takes that time out of the block. */
function segTrimHoles(from, to){
  if(!STATE.holes || !STATE.holes.length) return;
  var out = [];
  STATE.holes.forEach(function(hh){
    var a = new Date(hh.start).getTime(), b = new Date(hh.stop).getTime();
    if(b <= from || a >= to){ out.push(hh); return; }
    if(a < from) out.push({ id: uid("hl"), start: hh.start, stop: new Date(from).toISOString() });
    if(b > to) out.push({ id: uid("hl"), start: new Date(to).toISOString(), stop: hh.stop });
  });
  STATE.holes = out;
}
/* moving a start earlier (or a stop later) into the punch next to it used to be refused with
   "overlaps a neighbouring punch". Now that neighbour gives the time up: its stop (or start) moves to
   the new edge, as long as it keeps a minute and no third punch is in the way. */
function segTrimNeighbours(tp, s1, e1){
  var st = new Date(tp.start).getTime(), en = tp.stop ? new Date(tp.stop).getTime() : null, now = Date.now();
  var lows = [], highs = [];
  STATE.punches.forEach(function(x){
    if(x.id === tp.id) return;
    var xs = new Date(x.start).getTime(), xe = x.stop ? new Date(x.stop).getTime() : now;
    if(xs < st) lows.push({ p: x, s: xs, e: xe }); else highs.push({ p: x, s: xs, e: xe });
  });
  lows.sort(function(a, b){ return b.e - a.e; }); highs.sort(function(a, b){ return a.s - b.s; });
  var mark = function(x){ if(!x.edited){ x.edited = true; x.originalStart = x.start; x.originalStop = x.stop; } x.editedAt = nowIso(); };
  var did = [];
  var pv = lows[0];
  if(s1 < st && pv && s1 < pv.e && pv.p.stop && s1 - pv.s >= SEG_MIN && s1 >= (lows[1] ? lows[1].e : -Infinity)){
    mark(pv.p); pv.p.stop = new Date(s1).toISOString(); did.push(pv.p);
  }
  var nx = highs[0];
  if(en !== null && e1 !== null && e1 > en && nx && e1 > nx.s && e1 <= (highs[1] ? highs[1].s : Infinity) && (nx.p.stop ? nx.e - e1 >= SEG_MIN : e1 <= now - SEG_MIN)){
    mark(nx.p); nx.p.start = new Date(e1).toISOString(); did.push(nx.p);
  }
  return did;
}
function segSnap(ms){ var u = SEG_SNAP*60000; return Math.round(ms/u)*u; }
function segNudge(p, edge, mins){
  var d = mins*60000, s0 = new Date(p.start).getTime(), e0 = p.stop ? new Date(p.stop).getTime() : null, ok;
  pushUndo("adjust punch");
  if(edge === "s") ok = segApply(p, s0 + d, e0);
  else if(edge === "e") ok = p.stop ? segApply(p, s0, e0 + d) : false;
  else {
    if(!p.stop) ok = false;
    else {
      var bd = segBounds(p), len = e0 - s0, ns = Math.max(bd.lo, Math.min(bd.hi - len, s0 + d));
      ok = segApply(p, ns, ns + len);
    }
  }
  UI.segMsg = ok ? ((edge==="s"?"Start ":edge==="e"?"Stop ":"Moved ")+(mins>0?"+":"−")+Math.abs(mins)+" min · now "+fmtTime(p.start)+" – "+(p.stop?fmtTime(p.stop):"running")) : "Can't go further — it would overlap the next punch or go under a minute.";
  if(!ok) undoDropLast();
}
function undoDropLast(){ try{ if(typeof UNDO !== "undefined" && UNDO.length) UNDO.pop(); }catch(e){} }
/* the empty or air block right before / after a punch, and the punch beyond it */
function segGaps(dc, p){
  var out = { before: null, after: null };
  if(!dc || !dc.blocks) return out;
  var bl = dc.blocks.filter(function(b){ return b.ms > 0 && b.kind !== "seam"; });
  var i = -1;
  bl.forEach(function(b, k){ if(b.kind === "punch" && b.punch.id === p.id) i = k; });
  if(i < 0) return out;
  var ok = function(b){ return b && (b.kind === "empty" || (b.kind !== "punch" && b.kind !== "lunch" && b.kind !== "shop" && b.kind !== "off")); };
  /* a run of free time (air and empty blocks side by side) counts as one gap */
  var run = function(k, step){
    var j = k, from = null, to = null, empty = false;
    while(ok(bl[j]) && bl[j].at){
      var a0 = new Date(bl[j].at).getTime(), a1 = a0 + bl[j].ms;
      from = from === null ? a0 : Math.min(from, a0); to = to === null ? a1 : Math.max(to, a1);
      if(bl[j].kind === "empty") empty = true;
      j += step;
    }
    if(from === null) return null;
    var beyond = bl[j];
    return { at: from, ms: to - from, kind: empty ? "empty" : "air", nb: (beyond && beyond.kind === "punch" && beyond.punch.stop) ? beyond.punch : null };
  };
  out.before = run(i-1, -1);
  if(p.stop) out.after = run(i+1, 1);
  return out;
}
function segExtend(p, side, who){
  var dc = dailyCalc(localDay(p.start)), g = segGaps(dc, p), x = side === "b" ? g.before : g.after;
  if(!x) return;
  var from = x.at, to = x.at + x.ms, t, ok;
  pushUndo("fill gap");
  if(who === "nb" && x.nb){
    t = x.nb;
    ok = side === "b" ? segApply(t, new Date(t.start).getTime(), to) : segApply(t, from, new Date(t.stop).getTime());
  } else {
    ok = side === "b" ? segApply(p, from, p.stop ? new Date(p.stop).getTime() : null) : segApply(p, new Date(p.start).getTime(), to);
  }
  UI.segMsg = ok ? "Filled "+fmtClockHM(new Date(from))+" – "+fmtClockHM(new Date(to))+"." : "Couldn't fill that gap.";
  if(!ok) undoDropLast();
}
function segFocusSel(){
  setTimeout(function(){ var b = document.querySelector(".blk-punch.sel"); if(b) b.focus({ preventScroll: true }); }, 0);
}

/* drag the chevron handles: the move is measured against the bar's scale when the drag began */
var SEG_DRAG = null;
document.addEventListener("pointerdown", function(e){
  var hd = e.target.closest && e.target.closest(".seg-hd");
  if(!hd) return;
  var blk = hd.closest(".blk-punch"), seg = hd.closest(".seg");
  var p = blk && STATE.punches.filter(function(x){ return x.id === blk.dataset.punch; })[0];
  if(!p || !seg) return;
  e.preventDefault(); e.stopPropagation();
  pushUndo("adjust punch");
  SEG_DRAG = { p: p, edge: hd.dataset.edge, x0: e.clientX, w: seg.getBoundingClientRect().width, tt: +seg.dataset.tt,
               s0: new Date(p.start).getTime(), e0: p.stop ? new Date(p.stop).getTime() : null, moved: false, last: null,
               nb: STATE.punches.filter(function(x){ return x.id !== p.id; }).map(function(x){ return { x: x, s: x.start, e: x.stop, ed: x.edited, os: x.originalStart, oe: x.originalStop, ea: x.editedAt }; }) };
  document.documentElement.classList.add("seg-dragging");
}, true);
document.addEventListener("pointermove", function(e){
  if(!SEG_DRAG) return;
  var D = SEG_DRAG, dt = (e.clientX - D.x0) / D.w * D.tt;
  var ns = D.s0, ne = D.e0;
  if(D.edge === "s") ns = segSnap(D.s0 + dt); else ne = segSnap(D.e0 + dt);
  var key = ns + ":" + ne;
  if(key === D.last) return;
  D.last = key;
  var p = D.p;
  /* restart from the times at grab, so the clamp never drifts */
  p.start = new Date(D.s0).toISOString(); if(D.e0 !== null) p.stop = new Date(D.e0).toISOString();
  D.nb.forEach(function(n){ if(n.x.start !== n.s || n.x.stop !== n.e){ n.x.start = n.s; n.x.stop = n.e; n.x.edited = n.ed; n.x.originalStart = n.os; n.x.originalStop = n.oe; n.x.editedAt = n.ea; } });
  if((D.edge === "s" ? ns : ne) !== null) segTrimNeighbours(p, D.edge === "s" ? ns : D.s0, D.edge === "s" ? D.e0 : ne);
  if(D.edge === "s"){ var bd = segBounds(p); ns = Math.max(bd.lo, Math.min(ns, (ne !== null ? ne : Date.now()) - SEG_MIN)); }
  else { var bd2 = segBounds(p); ne = Math.min(bd2.hi, Math.max(ne, ns + SEG_MIN)); }
  if(segApply(p, ns, ne, true)){ D.moved = true; UI.segMsg = "Dragging · "+fmtTime(p.start)+" – "+(p.stop?fmtTime(p.stop):"running"); }
  if(!D.raf){ D.raf = requestAnimationFrame(function(){ D.raf = 0; render(); }); }
});
document.addEventListener("pointerup", function(){
  if(!SEG_DRAG) return;
  var D = SEG_DRAG; SEG_DRAG = null;
  document.documentElement.classList.remove("seg-dragging");
  if(!D.moved){ undoDropLast(); D.nb.forEach(function(n){ n.x.start = n.s; n.x.stop = n.e; n.x.edited = n.ed; n.x.originalStart = n.os; n.x.originalStop = n.oe; n.x.editedAt = n.ea; }); }
  else segTrimHoles(new Date(D.p.start).getTime(), D.p.stop ? new Date(D.p.stop).getTime() : Date.now());
  UI.segMsg = D.moved ? ((D.edge==="s"?"Start":"Stop")+" set to "+fmtTime(D.edge==="s"?D.p.start:D.p.stop)+".") : UI.segMsg;
  SEG_SWALLOW = Date.now();
  render(); segFocusSel();
});
var SEG_SWALLOW = 0;
document.addEventListener("click", function(e){
  if(Date.now() - SEG_SWALLOW < 400 && e.target.closest && e.target.closest(".seg")){ e.stopPropagation(); e.preventDefault(); }
}, true);

/* keyboard: arrows on the selected block or inside its panel */
document.addEventListener("keydown", function(e){
  if(!UI.segPick || UI.modal) return;
  var t = (e.composedPath && e.composedPath()[0]) || e.target;
  if(e.key === "Escape"){ e.preventDefault(); e.stopPropagation(); UI.segPick = null; UI.segMsg = ""; render(); return; }
  if(!t.closest || !(t.closest(".blk-punch.sel") || t.closest(".segedit"))) return;
  if(/^(input|textarea|select)$/i.test(t.tagName || "")) return;
  if(e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
  var p = STATE.punches.filter(function(x){ return x.id === UI.segPick; })[0]; if(!p) return;
  e.preventDefault(); e.stopPropagation();
  var dir = e.key === "ArrowRight" ? 1 : -1;
  if(e.altKey) segNudge(p, e.shiftKey ? "s" : "e", dir*5);
  else segNudge(p, "m", dir*(e.shiftKey ? 15 : 5));
  var inPanel = !!t.closest(".segedit");
  render(); if(!inPanel) segFocusSel();
}, true);

/* hovering an air block unrolls its note flag */
document.addEventListener("mouseover", function(e){
  var t = e.target && e.target.closest ? e.target.closest('.seg-block[data-action="seg-air"], .air-flag') : null;
  document.querySelectorAll(".air-flag.open").forEach(function(f){ if(!t || f.dataset.at !== t.dataset.at) f.classList.remove("open"); });
  if(!t) return;
  var w = t.closest(".segwrap"); if(!w) return;
  var f = w.querySelector('.air-flag[data-at="'+t.dataset.at+'"]'); if(f) f.classList.add("open");
});
/* ---------- air & lunch blocks: click to change the reason or the times ---------- */
/* The reason is the stop reason of the punch just before the gap (so "Lunch" turns it
   red); the times are that punch's stop and the next punch's start. */
/* the note written on an air / lunch / shop block — kept on the punch before it (or the one after, when nothing comes before) */
function airNoteFor(b){
  var pp = b.prevId ? STATE.punches.filter(function(x){ return x.id === b.prevId; })[0] : null;
  if(pp) return String(pp.airNote || "").trim();
  var nx = b.nextId ? STATE.punches.filter(function(x){ return x.id === b.nextId; })[0] : null;
  return nx ? String(nx.airNoteBefore || "").trim() : "";
}
function airPicked(dc, b){ var a = UI.segAir; return !!(a && a.day === dc.date && a.at === b.at); }
function airBlockFor(dc){
  var a = UI.segAir; if(!a || a.day !== dc.date) return null;
  return dc.blocks.filter(function(b){ return (b.kind === "air" || b.kind === "lunch" || b.kind === "shop") && b.at === a.at; })[0] || null;
}
var AIR_REASON_GROUPS = [
  ["Stepping away", ["Lunch","Appointment","Emergency","Home","End of day"]],
  ["Waiting", ["Waiting – Parts","Waiting – Foreman","Waiting – Tech Support","Waiting – Approval","Waiting – New Job"]],
  ["Switching work", ["Switched job","Pulled to another truck"]]
];
function airPopHtml(winStart, winTotal, dc){
  if(!UI.segAir || UI.segAir.day !== dc.date) return "";
  var b = airBlockFor(dc);
  if(!b){ UI.segAir = null; return ""; }
  var prev = b.prevId ? STATE.punches.filter(function(x){ return x.id===b.prevId; })[0] : null;
  var next = STATE.punches.filter(function(x){ return x.id===b.nextId; })[0] || null;
  var from = new Date(b.at), to = new Date(from.getTime() + b.ms);
  var mid = (from.getTime() + b.ms/2 - winStart.getTime()) / winTotal * 100;
  mid = Math.min(Math.max(mid, 14), 86);
  var cur = prev ? (prev.stopReason || "") : "";
  if(AIR_NO_LABEL.indexOf(cur) !== -1) cur = "";
  var known = !cur || AIR_REASON_GROUPS.some(function(g){ return g[1].indexOf(cur) !== -1; });
  var roLine = function(p){ if(!p) return "—"; var ro = getRO(p.roId); return 'RO '+esc(ro?ro.roNumber:"?"); };
  var h = '<div class="segpop airpop" style="left:'+mid.toFixed(2)+'%">'
    + '<div class="sp-top"><span class="sp-kind '+b.kind+'">'+(b.kind==="lunch"?"Lunch":b.kind==="shop"?"Shop time":"Air time")+'</span>'
    +   '<span class="sp-when mono">'+fmtClockHM(from)+' – '+fmtClockHM(to)+' · '+fmtHM(b.ms)+'</span>'
    +   '<button class="sp-x" data-action="seg-close" title="Close" aria-label="Close">✕</button></div>'
    + '<div class="sp-what ap-between">After '+roLine(prev)+' → before '+roLine(next)+'</div>';
  var nHost = prev || next, nKey = prev ? "airNote" : "airNoteBefore";
  h += '<div class="ap-lbl">Note</div><textarea class="ap-input ap-notein" data-airnote="'+(nHost ? nHost.id : '')+'" data-k="'+nKey+'" maxlength="300" rows="2" placeholder="What the time went to — e.g. waited on the road-test truck, bay was full, looked for a part"'+(nHost ? '' : ' disabled')+'>'+esc(nHost ? (nHost[nKey] || '') : '')+'</textarea>'
    + '<div class="hint ap-note">Shows when you point at this block on the day bar.</div>';
  h += '<div class="ap-lbl">Time</div>'
    + '<div class="ap-times"><label>From <input type="time" id="air-from" class="ap-input mono" value="'+fmtClockHM(from)+'"'+(prev?'':' disabled title="Starts where a deleted punch ended"')+'></label>'
    +   '<label>To <input type="time" id="air-to" class="ap-input mono" value="'+fmtClockHM(to)+'"'+(next?'':' disabled')+'></label>'
    +   '<button class="btn btn-sm btn-primary" data-action="air-times">Save times</button></div>'
    + '<div class="ap-foot"><button class="btn btn-sm btn-danger" data-action="air-delete" title="Take this block off the day \u2014 it becomes an empty slot and stops counting">'+IC.trash+'<span>Delete '+(b.kind==="lunch"?"lunch":b.kind==="shop"?"shop time":"air time")+'</span></button></div>'
    + '<div class="hint ap-note">Moving <b>From</b> changes when '+roLine(prev)+' stopped; moving <b>To</b> changes when '+roLine(next)+' started.</div>'
    + '</div>';
  return h;
}
function airSetReason(dc, reason){
  var b = airBlockFor(dc); if(!b || !b.prevId) return;
  var p = STATE.punches.filter(function(x){ return x.id===b.prevId; })[0]; if(!p || !p.stop) return;
  if((p.stopReason||"") === (reason||"")) return;
  pushUndo("change air reason");
  if(!p.reasonEdited){ p.reasonEdited = true; p.origStartReason = p.startReason; p.origStopReason = p.stopReason; }
  p.stopReason = reason || null; p.editedAt = nowIso();
  scheduleSave(true);
  pushToast(reason ? "Air reason: "+reason : "Air reason cleared", true);
}
/* delete: the gap becomes an empty slot (like a deleted punch) — no longer air, lunch or shop time */
function airDelete(dc){
  var b = airBlockFor(dc); if(!b) return;
  var from = new Date(b.at), to = new Date(from.getTime() + b.ms);
  pushUndo("delete " + (b.kind === "air" ? "air time" : b.kind === "shop" ? "shop time" : "lunch"));
  STATE.holes = STATE.holes || [];
  STATE.holes.push({ id: uid("hl"), start: from.toISOString(), stop: to.toISOString() });
  UI.segAir = null;
  scheduleSave(true);
  pushToast((b.kind === "air" ? "Air time" : b.kind === "shop" ? "Shop time" : "Lunch") + " deleted", true);
}
/* ---------- empty slots (a deleted punch or deleted air): fill with a punch, or count it as air again ---------- */
function emptyPicked(dc, b){ var a = UI.segEmpty; return !!(a && a.day === dc.date && a.at === b.at); }
function emptyBlockFor(dc){
  var a = UI.segEmpty; if(!a || a.day !== dc.date) return null;
  return dc.blocks.filter(function(b){ return b.kind === "empty" && b.at === a.at; })[0] || null;
}
function emptyPopHtml(winStart, winTotal, dc){
  if(!UI.segEmpty || UI.segEmpty.day !== dc.date) return "";
  var b = emptyBlockFor(dc);
  if(!b){ UI.segEmpty = null; return ""; }
  var from = new Date(b.at), to = new Date(from.getTime() + b.ms);
  var mid = (from.getTime() + b.ms/2 - winStart.getTime()) / winTotal * 100;
  mid = Math.min(Math.max(mid, 14), 86);
  return '<div class="segpop airpop emptypop" style="left:'+mid.toFixed(2)+'%">'
    + '<div class="sp-top"><span class="sp-kind empty">Empty</span>'
    +   '<span class="sp-when mono">'+fmtClockHM(from)+' \u2013 '+fmtClockHM(to)+' \u00b7 '+fmtHM(b.ms)+'</span>'
    +   '<button class="sp-x" data-action="seg-close" title="Close" aria-label="Close">\u2715</button></div>'
    + '<div class="sp-what ap-between">Nothing is logged here \u2014 the time left by a deleted punch or deleted air time. It counts as nothing.</div>'
    + '<div class="ap-acts">'
    +   '<button class="btn btn-sm btn-primary" data-action="empty-fill" title="Add a punch that covers this time">'+IC.clockPlus+'<span>Fill with a punch\u2026</span></button>'
    +   '<button class="btn btn-sm" data-action="empty-air" title="Stop treating this as empty \u2014 it counts as air time again">Count as air time</button>'
    + '</div></div>';
}
/* two punches by the same tech at the same time — the day's burnt time is counted twice */
function overlapBadgeHtml(dc){
  var P = (dc.punches || []).slice().sort(function(a, b){ return new Date(a.start) - new Date(b.start); }), hits = [];
  for(var i = 1; i < P.length; i++) for(var j = 0; j < i; j++){
    if((P[i].by || "") !== (P[j].by || "")) continue;
    if(new Date(P[i].start) < new Date(P[j].stop || Date.now()) - 59000) hits.push(fmtTime(P[j].start) + "\u2013" + (P[j].stop ? fmtTime(P[j].stop) : "now") + " and " + fmtTime(P[i].start) + "\u2013" + (P[i].stop ? fmtTime(P[i].stop) : "now"));
  }
  if(!hits.length) return "";
  var tip = hits.length + " overlapping punch" + (hits.length === 1 ? "" : "es") + ": " + hits.join("; ") + ". The same time is counted twice \u2014 shorten or delete one of them.";
  return '<span class="tl-warn tl-ovl" role="status" tabindex="0" title="'+esc(tip)+'" aria-label="'+esc(tip)+'">'+IC.warn+'<b>'+hits.length+' overlap'+(hits.length === 1 ? '' : 's')+'</b></span>';
}
function emptyBadgeHtml(dc){
  var eb = (dc.blocks || []).filter(function(b){ return b.kind === "empty"; });
  if(!eb.length) return "";
  var tot = eb.reduce(function(n,b){ return n + b.ms; }, 0);
  var tip = eb.length + " empty block" + (eb.length===1?"":"s") + " (" + fmtHM(tot) + ") on this day: "
    + eb.map(function(b){ var f = new Date(b.at); return fmtClockHM(f)+"\u2013"+fmtClockHM(new Date(f.getTime()+b.ms)); }).join(", ")
    + ". A segment should be added \u2014 this stays until every empty block is filled.";
  return '<span class="tl-warn" role="status" tabindex="0" title="'+esc(tip)+'" aria-label="'+esc(tip)+'">'+IC.warn+'<b>'+eb.length+'</b></span>';
}
function emptyRestore(dc){
  var b = emptyBlockFor(dc); if(!b) return;
  var from = new Date(b.at).getTime(), to = from + b.ms;
  var hit = (STATE.holes || []).filter(function(hh){ return new Date(hh.start).getTime() < to && new Date(hh.stop).getTime() > from; });
  if(!hit.length) return;
  pushUndo("restore air time");
  var keep = [];
  (STATE.holes || []).forEach(function(hh){
    if(hit.indexOf(hh) === -1){ keep.push(hh); return; }
    var hs = new Date(hh.start).getTime(), he = new Date(hh.stop).getTime();
    if(hs < from) keep.push({ id: uid("hl"), start: hh.start, stop: new Date(from).toISOString() });   /* parts outside this block stay empty */
    if(he > to) keep.push({ id: uid("hl"), start: new Date(to).toISOString(), stop: hh.stop });
  });
  STATE.holes = keep;
  UI.segEmpty = null;
  scheduleSave(true);
  pushToast("Counted as air time again", true);
}
function airSetTimes(dc, fromHM, toHM){
  var b = airBlockFor(dc); if(!b) return;
  var prev = b.prevId ? STATE.punches.filter(function(x){ return x.id===b.prevId; })[0] : null;
  var next = STATE.punches.filter(function(x){ return x.id===b.nextId; })[0] || null;
  var oldFrom = new Date(b.at), oldTo = new Date(oldFrom.getTime() + b.ms);
  var at = function(hm, base){ if(!hm) return base; var d = new Date(base); var q = hm.split(":"); d.setHours(+q[0], +q[1], 0, 0); return d; };
  var nf = (prev && fromHM && fromHM !== fmtClockHM(oldFrom)) ? at(fromHM, oldFrom) : oldFrom;
  var nt = (next && toHM && toHM !== fmtClockHM(oldTo)) ? at(toHM, oldTo) : oldTo;
  if(+nf === +oldFrom && +nt === +oldTo) return;
  if(!(nt > nf)) { pushToast("To must be after From."); return; }
  if(prev && !(nf > new Date(prev.start))) { pushToast("From must be after that punch started ("+fmtClockHM(new Date(prev.start))+")."); return; }
  if(next && !(nt < new Date(next.stop || Date.now()))) { pushToast("To must be before that punch stopped."); return; }
  var clash = function(p, a, z){ return STATE.punches.some(function(o){ return o !== p && o !== prev && o !== next && a < new Date(o.stop || Date.now()) && z > new Date(o.start); }); };
  if(prev && +nf !== +oldFrom && clash(prev, new Date(prev.start), nf)) { pushToast("That overlaps another punch."); return; }
  if(next && +nt !== +oldTo && clash(next, nt, new Date(next.stop || Date.now()))) { pushToast("That overlaps another punch."); return; }
  pushUndo("edit air time");
  var mark = function(p){ if(!p.edited){ p.edited = true; p.originalStart = p.start; p.originalStop = p.stop; } p.editedAt = nowIso(); };
  if(prev && +nf !== +oldFrom){ mark(prev); prev.stop = nf.toISOString(); }
  if(next && +nt !== +oldTo){ mark(next); next.start = nt.toISOString(); }
  UI.segAir.at = nf.toISOString();
  scheduleSave(true);
  pushToast("Air time now "+fmtClockHM(nf)+" – "+fmtClockHM(nt));
}

function deletePunch(id){
  var i = STATE.punches.findIndex(function(x){ return x.id===id; });
  if(i < 0) return;
  var p = STATE.punches[i];
  pushUndo("delete punch");
  audit("punch-del", "Deleted a punch on " + (getRO(p.roId) ? roLabel(getRO(p.roId)) : "an RO") + " (" + fmtTime(p.start) + (p.stop ? "\u2013" + fmtTime(p.stop) : "") + ")", getRO(p.roId));
  if(p.stop){
    STATE.holes = STATE.holes || [];
    STATE.holes.push({ id: uid("hl"), start: p.start, stop: p.stop });
  }
  STATE.punches.splice(i,1);
  UI.segPick = null;
  scheduleSave(true);
}

/* A slot stops existing the moment real time is logged over it. */
function pruneHoles(state){
  if(!state.holes || !state.holes.length) return;
  state.holes = state.holes.filter(function(hh){
    var hs = new Date(hh.start), he = new Date(hh.stop);
    if(!(he > hs)) return false;
    return !state.punches.some(function(p){
      if(!p.stop) return false;
      return new Date(p.start) < he && new Date(p.stop) > hs;
    });
  });
}

function fmtClockHM(d){ return String(d.getHours()).padStart(2,"0") + ":" + String(d.getMinutes()).padStart(2,"0"); }

/* Where does the filter text appear on this RO? null = nowhere, "" = the obvious fields,
   otherwise a short note like "PN 4988201" shown on the RO card. */
function roMatch(ro, filter){
  if(!filter) return "";
  var f = String(filter).toLowerCase().trim();
  if(!f) return "";
  function has(v){ return v != null && String(v).toLowerCase().indexOf(f) !== -1; }
  if(has(ro.roNumber) || has(ro.customerName) || has(ro.caseNumber) || has(ro.unitNumber)) return "";
  var ops = ro.operations || [], i, j;
  for(i = 0; i < ops.length; i++) if(has(ops[i].complaint)) return "";
  var fc = f.replace(/\s+/g, "");
  if(ro.vin && String(ro.vin).toLowerCase().indexOf(fc) !== -1) return "VIN …" + String(ro.vin).slice(-8);
  if(has(ro.keyTag)) return "Tag " + ro.keyTag;
  if(has(ro.location)) return "Location " + ro.location;
  for(i = 0; i < ops.length; i++){
    var parts = ops[i].parts || [];
    for(j = 0; j < parts.length; j++){
      if(has(parts[j].partNumber)) return "PN " + parts[j].partNumber;
      if(has(parts[j].description)) return "Part: " + parts[j].description;
    }
  }
  for(i = 0; i < ops.length; i++){
    var txt = String(ops[i].work || "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ");
    var k = txt.toLowerCase().indexOf(f);
    if(k === -1 && fc !== f) k = txt.toLowerCase().replace(/\s+/g, "").indexOf(fc) === -1 ? -1 : 0;
    if(k !== -1) return "Work: …" + txt.substr(Math.max(0, k - 12), 40).trim() + "…";
    var logs = ops[i].log || [];
    for(j = 0; j < logs.length; j++) if(has(logs[j].text)) return "Log: …" + String(logs[j].text).slice(0, 36) + "…";
  }
  if(has(ro.techNote)) return "Note: \u2026" + String(ro.techNote).replace(/\s+/g, " ").trim().slice(0, 36) + "\u2026";
  var bl = ro.bulletins || [];
  for(i = 0; i < bl.length; i++){
    var fl = bl[i].fields || {};
    for(var key in fl) if(has(fl[key])) return "Note: …" + String(fl[key]).slice(0, 36) + "…";
    if(has(bl[i].place)) return "Location " + bl[i].place;
    var files = bl[i].files || [];
    for(j = 0; j < files.length; j++) if(has(files[j].name)) return "File " + files[j].name;
  }
  return null;
}
function roMatchesFilter(ro, filter){ return roMatch(ro, filter) !== null; }

var RO_GROUPS = [["all","All"],["working","Working"],["waiting","Waiting"],["hold","Hold"]];
function roGroupOf(ro){
  if(roIsDone(ro)) return "done";
  var s = roStatus(ro).status;
  if(s === "Working") return "working";
  if(/^Waiting/.test(s)) return "waiting";
  return "hold";
}
function visibleRos(){
  var g = UI.roGroup || "all";
  return sortedROs().filter(function(ro){
    if(!roMatchesFilter(ro, UI.roFilter) || !roInScope(ro)) return false;
    if(!(g === "all" || roGroupOf(ro) === g || roGroupOf(ro) === "done")) return false;
    return true;
  });
}
function viewROs(){
  roFitWidths();
  var ros = visibleRos();
  var openN = STATE.ros.filter(function(ro){ return !roIsDone(ro); }).length, doneN = STATE.ros.length - openN;
  /* no page header here — the RO list and the console start at the top */
  var roHead = '';
  var openN = STATE.ros.filter(function(ro){ return !roIsDone(ro); }).length, doneN = STATE.ros.length - openN;

  if(!STATE.ros.length){
    return roHead + '<div class="inv-empty">'+esHtml('doc', 'No repair orders open', 'Add the first RO, or load the 5 sample trucks to look around.',
      '<button class="btn btn-primary" data-action="open-add-ro">'+IC.plus+'<span>New repair order</span></button>'
      + '<button class="btn" data-action="load-sample">'+IC.sample+'<span>Generate 25 samples</span></button>')+'</div>';
  }

  // keep a valid selection
  var sel = UI.selectedRo;
  if(sel !== SHOP_RO_ID && (!sel || !getRO(sel))) sel = ros.length ? ros[0].id : (STATE.ros[0] ? STATE.ros[0].id : null);
  UI.selectedRo = sel;
  if(!Array.isArray(UI.recentRos)) UI.recentRos = [];
  if(sel && UI.recentRos[0] !== sel) UI.recentRos = [sel].concat(UI.recentRos.filter(function(x){ return x !== sel && getRO(x); })).slice(0, 6);

  var railMini = true;
  railWasMini = railMini;
  UI.roPaneShut = false;
  var shutP = railMini;
  var h = roHead + '<div class="ro-page'+(railMini?" rail-hidden":"")+'">';

  /* the RO list is its own page now (RO List) — this page opens on one RO, with a line to go back */
  /* no back line — the browser's Back button goes back to the RO List */

  /* ---- detail: the selected RO ---- */
  h += sel ? '<div class="ro-detail-pane jc-pane" data-jc="'+sel+'" data-scroll="ro-pane"></div>'
           : '<div class="ro-detail-pane"><div class="empty"><h3>Nothing selected</h3></div></div>';
  /* the day bar is gone from this page — the Time Log and the Console still carry it */
  h += '</div>';
  return h;
}

/* ---------- the profile button ----------
   A round button, top right of the header, showing the technician's initials
   (or a generic person icon until a name is set). Pops a small card to set it. */
function profileInitials(name){
  var s = String(name || "").trim();
  if(!s) return "";
  var parts = s.split(/\s+/).filter(Boolean);
  var a = parts[0] ? parts[0][0] : "", b = parts.length > 1 ? parts[parts.length - 1][0] : "";
  return (a + b).toUpperCase();
}
