  var bgs = [["#5d7189","#2e3a4a"],["#a9b4a0","#566453"],["#8a7a66","#463c31"],["#7f8ea3","#3a465a"],["#9bb0a8","#4d6159"],["#8f9aa8","#414b59"],["#a08aa8","#4f4159"],["#a8968a","#5a4a40"]];
  var av = { f: f, skin: t[0], shade: t[1], hair: R(["#15110e","#1b1411","#3a2216","#5a3a22","#8a4a22","#b07a3a","#2a2420","#0a0807"]),
    style: st, beard: f ? "none" : R(["none","none","stubble","mustache","full"]), shirt: shirt,
    sc: shirt === "hivis" ? "#c9d62b" : R(["#27425f","#2c4a3f","#3b3f46","#4a4f57","#5b2a2a","#2f3b6b"]),
    eye: R(["#3a2a1c","#2a1b12","#4d7a8c","#4a3322","#33231a","#5a6a3a"]), bg: R(bgs), age: age, glasses: Math.random() < 0.25 };
  if(st === "cap") av.cap = R(["#a3262a","#1f4e8c","#2d5a2d","#333","#c27a12"]);
