  var c = M.cur, tone = !c ? "d" : c.state === "w" ? "w" : c.state === "c" ? "c" : "n";
  return '<span class="rs-b" title="' + esc(M.list.map(function(x){ return x.name + ": " + (x.state === "d" ? "done" : x.state === "x" ? "not needed" : x.state === "t" ? "to do" : x.sub); }).join("\n")) + '">'
    + '<span class="rs-segs">' + M.list.map(function(x){ return '<i class="rs-sg ' + x.state + '"></i>'; }).join("") + '</span>'
    + '<span class="rs-now ' + tone + '"><i></i>' + (c ? esc(c.name) + ' · ' + esc(c.sub) : 'All ' + M.total + ' stages done') + '</span></span>';
