  var ro = getRO(pane.getAttribute("data-jc"));
  if(!ro) return;
  migrateRO(ro);
  JC.attach(pane, ro);
  try{ raMount(pane, ro); }catch(e){ console.error(e); }
  var oldSeam = pane.querySelector(":scope > .seam-dock"); if(oldSeam) oldSeam.remove();
