  body += '<div class="tg-sec' + (UI.fmOpen.clr ? ' open' : '') + '" data-action="fm-open" data-k="clr">' + tgI("chevR", 12) + '<span>Cleared today</span><span class="n">' + cl.length + '</span></div>'
