    toast(add.length + ' part' + (add.length === 1 ? '' : 's') + ' added to ' + (job.complaint || 'the operation') + (nInv ? ' \u00b7 ' + nInv + ' new on the Parts page' : ''), { label: 'UNDO', run: function () { restoreSnapshot(); } });
